-- Ultimate / Blessed decoded register-source
-- Reconstructed from the user-supplied Blessed script. Original names and
-- comments are unavailable. Numeric program counters preserve recovered flow.
-- Original UI and gameplay functions are retained; this is not Ultimate 1.1.
local BRAND = "Ultimate"
local prototypes, functions, prototypeNames = {}, {}, {}
local customizeClosure, UltimateExtensions
local unpackValues = table.unpack or unpack
local function slice(first, values, last) return unpackValues(values, first, last or #values) end
local function packValues(...) return select("#", ...), {...} end
local function iterate(iterator, state, control)
    if type(iterator)=="table" then
        local mt=getmetatable(iterator)
        if type(mt)=="table" and type(mt.__iter)=="function" then return mt.__iter(iterator) end
        return next,iterator,nil
    end
    return iterator,state,control
end
local function array() return {} end
local bitFunctions={
    [6]=bit32.countrz,[7]=bit32.bxor,[8]=bit32.bor,[9]=bit32.lshift,
    [10]=bit32.lrotate,[11]=bit32.band,[12]=bit32.countlz,[13]=bit32.bnot,
    [14]=bit32.rshift,[15]=bit32.rrotate,[16]=string.unpack
}
local function getEnvironment() return getfenv and getfenv() or _G end
local function makeClosure(prototype, upvalues, environment)
    local name=prototypeNames[prototype]
    local original=functions[name](environment, upvalues)
    return customizeClosure and customizeClosure(name,original,environment,upvalues) or original
end

-- Editable Ultimate preferences layered over the recovered Blessed program.
local UltimatePreferences = {
    AutoGuardKey = "L", HideAimbotKeyPicker = true,
    ShotDelay = 0.28, AimbotType = "High", Aimbot = true, AutoGuard = true, BallCheck = true,
    MatchTargetJump = true, AutoPlay = false,
    BallMagnet = false, MagnetStrength = 50,
    BallReach = true, ReachStrength = 10,
    WalkSpeed = 0.01, AntiDrop = true,
    LogoURL = "https://raw.githubusercontent.com/OfficialUltimateMacro/Ultimate-Hoopz/main/assets/ultimate-wordmark.png",
    LogoCache = "Ultimate-wordmark-061784a8.png"
}
local ULTIMATE_LOGO_TOKEN = "ultimate://wordmark"
local logoImage, logoAttempted
local function resolveUltimateLogo(environment)
    if logoAttempted then return logoImage end
    logoAttempted = true
    local customAsset = environment.getcustomasset or environment.getsynasset
    if type(customAsset) ~= "function" or type(environment.writefile) ~= "function" then return nil end
    local ok, value = pcall(function()
        if type(environment.isfile) ~= "function" or not environment.isfile(UltimatePreferences.LogoCache) then
            local bytes = environment.game:HttpGet(UltimatePreferences.LogoURL)
            assert(type(bytes) == "string" and bytes:sub(1, 8) == "\137PNG\r\n\26\n", "Logo download was not a PNG")
            environment.writefile(UltimatePreferences.LogoCache, bytes)
        end
        return customAsset(UltimatePreferences.LogoCache)
    end)
    if ok and type(value) == "string" and value ~= "" then logoImage = value end
    return logoImage
end
local function applyUltimateProperty(target, key, value, environment)
    if UltimateExtensions then UltimateExtensions:ObserveInstance(target, key, value, environment) end
    if key == "Image" and value == ULTIMATE_LOGO_TOKEN
        and environment.typeof(target) == "Instance" then
        local resolved = resolveUltimateLogo(environment)
        target.Image = resolved or ""
        target.ScaleType = environment.Enum.ScaleType.Fit
        if not resolved and not target:FindFirstChild("UltimateWordmark") then
            local wordmark = environment.Instance.new("TextLabel")
            wordmark.Name = "UltimateWordmark"
            wordmark.BackgroundTransparency = 1
            wordmark.Size = environment.UDim2.fromScale(1, 1)
            wordmark.Text = BRAND
            wordmark.Font = environment.Enum.Font.Fantasy
            wordmark.TextColor3 = environment.Color3.fromRGB(255, 113, 175)
            wordmark.TextStrokeColor3 = environment.Color3.fromRGB(54, 10, 36)
            wordmark.TextStrokeTransparency = 0
            wordmark.TextScaled = true
            wordmark.ZIndex = target.ZIndex + 1
            wordmark.Parent = target
        end
    else target[key] = value end
end
local function applyUltimateDefaults(root)
    -- The original decoded data stays untouched on disk. These sites are the
    -- recovered initializer operations, applied before self-modification runs.
    assert(root[6][1972] == "X", "Unexpected aimbot initializer")
    assert(root[6][1976] == 0.32, "Unexpected shot delay initializer")
    root[6][1976] = UltimatePreferences.ShotDelay
    root[6][1974] = UltimatePreferences.AimbotType
    root[6][1969] = UltimatePreferences.Aimbot
    root[6][1972] = "Unknown" -- The initializer assignment itself is skipped.
    root[6][1978] = UltimatePreferences.AutoGuard
    root[6][1979] = UltimatePreferences.BallCheck
    root[6][2038] = UltimatePreferences.AutoGuardKey
    root[6][1399] = "Auto Guard key"
    root[6][1977] = UltimatePreferences.WalkSpeed
    root[6][2009] = UltimatePreferences.BallReach
    root[6][2010] = UltimatePreferences.ReachStrength
    root[6][2011] = UltimatePreferences.AntiDrop
    root[6][2040] = UltimatePreferences.BallMagnet
    root[6][2041] = UltimatePreferences.MagnetStrength
end

-- Readable additions to Blessed. Acquisition stays in its original Ball Check
-- selector; jump matching subscribes to that selector's current player only.
UltimateExtensions = {
    Alive = true, Connections = {}, LastJump = -100, LastShot = -100,
    LastBallScan = -100, Clock = 0, AutoPlayStatus = "Off", ManualUntil = 0
}
local Extension = UltimateExtensions
local function disconnect(connection) if connection then connection:Disconnect() end end
local function characterParts(player)
    local character = player and player.Character
    if not character or not character.Parent then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local root = character:FindFirstChild("HumanoidRootPart")
    if humanoid and root and humanoid.Health > 0 then return character, humanoid, root end
end
-- Possession. Blessed's own selector counts a player as the handler only when
-- Character.Basketball contains a "Ball"; an empty container can remain after
-- a turnover. Once that layout has been observed, require it.
local BallLayout = {Learned = false}
local function heldBall(character)
    local container = character and character:FindFirstChild("Basketball")
    if not container then return nil end
    local ok, ball = pcall(function() return container.FindFirstChild and container:FindFirstChild("Ball") end)
    if ok and ball then BallLayout.Learned = true; return container end
    if BallLayout.Learned then return nil end
    return container
end
local function distance(a, b)
    return (a - b).Magnitude
end
-- Bounded diagnostics: a ring buffer of transitions/events, never per-frame.
function Extension:Log(kind, text)
    local log = self.EventLog or {}
    self.EventLog = log
    local stamp = string.format("T+%.1f", self.Clock-(self.AutoPlayStarted or 0))
    local okDate, wall = pcall(function() return os.date("%H:%M:%S") end)
    if okDate and wall then stamp = wall.." "..stamp end
    self.EventSequence=(self.EventSequence or 0)+1
    log[#log+1] = stamp.." [run "..tostring(self.RunSerial or 0).." #"..self.EventSequence.."] "..kind..": "..tostring(text)
    if #log > 60 then table.remove(log, 1) end
end
function Extension:CaptureTrace()
    if not self.Settings.AutoPlay or self.Clock<(self.NextTrace or -100) then return end
    self.NextTrace=self.Clock+0.5
    local _,h,root=characterParts(self.Player)
    if not root then return end
    local goal=self.OffenseGoal or self.MatchGoal
    local power="?";pcall(function()power=tostring(self.Player:GetAttribute("Power"))end)
    local row=string.format("run="..tostring(self.RunSerial or 0).." T+%.2f state=%s pos=(%.1f,%.1f,%.1f) speed=%.1f rim=%.1f power=%s shield=%s setup=%s move=%s route=%s shot=%s",
        self.Clock-(self.AutoPlayStarted or 0),tostring(self.State),root.Position.X,root.Position.Y,root.Position.Z,
        root.AssemblyLinearVelocity.Magnitude,goal and distance(root.Position,goal.Position) or -1,power,
        tostring(self.ProtectFacing==true),tostring(self.PreparingShot==true),tostring(self.DribbleStatus),
        tostring(self.AutoPlayStatus),tostring(self.ShotBlockReason))
    self.TraceLog=self.TraceLog or {};table.insert(self.TraceLog,row)
    if #self.TraceLog>120 then table.remove(self.TraceLog,1) end
end
function Extension:Connect(signal, callback)
    local connection = signal:Connect(callback)
    self.Connections[#self.Connections + 1] = connection
    return connection
end
function Extension:ClearTarget()
    disconnect(self.JumpConnection)
    self.JumpConnection, self.Target, self.TargetCharacter, self.TargetHumanoid = nil, nil, nil, nil
end
function Extension:IsManual()
    local input, enum = self.Input, self.Environment.Enum
    if input:GetFocusedTextBox() then self.ManualReason = "typing"; return true end
    for _, name in ipairs({"W", "A", "S", "D", "Up", "Down", "Left", "Right"}) do
        if input:IsKeyDown(enum.KeyCode[name]) then self.ManualUntil = self.Clock + 0.3; self.ManualReason = name; return true end
    end
    -- A physical Space press is a manual jump/shot; ignore our own synthetic
    -- Space pulses and the jump an Auto-play shot is performing.
    local space = enum.KeyCode.Space
    if space and input:IsKeyDown(space) and not self.Shooting and not self.ExecutorJumpHeld
        and not (self.DribbleKeys and self.DribbleKeys[space]) then
        self.ManualUntil = self.Clock + 0.3; self.ManualReason = "Space"; return true
    end
    return self.Clock < self.ManualUntil
end
function Extension:MirrorJump(player, humanoid)
    if not self.Alive or not self.Settings or not (self.Settings.AutoGuard or self.Settings.AutoPlay)
        or not self.Settings.AutoGuardJumpMatch or self:IsManual() then return false end
    -- Re-run the SAME selector, including Ball Check and its 50-stud limit.
    local selected = self.Selector and self.Selector()
    if selected ~= player then self:SelectTarget(selected); return false end
    if self.Target ~= player or self.TargetHumanoid ~= humanoid or player.Character ~= self.TargetCharacter then return false end
    local ownCharacter, ownHumanoid = characterParts(self.Player)
    if not ownHumanoid or heldBall(ownCharacter) or ownHumanoid.FloorMaterial == self.Environment.Enum.Material.Air
        or self.Clock - self.LastJump < 0.25 then return false end
    ownHumanoid.Jump, self.LastJump = true, self.Clock
    return true
end
function Extension:SelectTarget(player)
    local character, humanoid, root = characterParts(player)
    if self.Target == player and self.TargetCharacter == character and self.TargetHumanoid == humanoid then return end
    self:ClearTarget()
    if not character or not self.Settings or not (self.Settings.AutoGuard or self.Settings.AutoPlay) then return end
    self.Target, self.TargetCharacter, self.TargetHumanoid = player, character, humanoid
    self.JumpConnection = humanoid.Jumping:Connect(function(active)
        if active then self:MirrorJump(player, humanoid) end
    end)
    -- Also catch a jump already underway when a new carrier is selected.
    if humanoid.FloorMaterial == self.Environment.Enum.Material.Air and root.AssemblyLinearVelocity.Y > 1 then
        self:MirrorJump(player, humanoid)
    end
end
function Extension:SetFeature(name, value)
    local captures = self.InputCaptures
    local toggle = captures and captures[name == "Aimbot" and 1 or (name == "AutoGuard" and 3 or -1)]
    self.Settings[name] = value
    if toggle and type(toggle.SetValue) == "function" then pcall(toggle.SetValue, value) end
    if name == "AutoGuard" and not value then self:ClearTarget() end
end
function Extension:GuardKey(input, processed, captures)
    if not self.Alive or processed or self.Input:GetFocusedTextBox() then return end
    local settings = captures[0] or self.Settings
    if settings and settings.AutoPlayKeybind and input.KeyCode == settings.AutoPlayKeybind
        and input.KeyCode ~= settings.AutoGuardKeybind then
        self.Settings, self.InputCaptures = settings, captures
        self:SetAutoPlay(not settings.AutoPlay)
        if captures[2] and type(captures[2].Notification) == "function" then
            pcall(function()
                captures[2].Notification().new({Title = "Auto-play", Description = settings.AutoPlay and "Enabled" or "Disabled", Duration = 2})
            end)
        end
        return
    end
    if not settings or input.KeyCode ~= settings.AutoGuardKeybind then return end
    self.Settings, self.InputCaptures = settings, captures
    local enabled = not settings.AutoGuard
    self:SetFeature("AutoGuard", enabled)
    -- Guard-only notification: never fall through into the old Aimbot branch.
    if captures[2] and type(captures[2].Notification) == "function" then
        pcall(function()
            captures[2].Notification().new({Title = "Auto Guard", Description = enabled and "Enabled" or "Disabled", Duration = 2})
        end)
    end
end
function Extension:StopAutoMove()
    self.AutoMovePoint, self.LastMoveToPoint = nil, nil
    if self.AutoMoving then
        local _, humanoid, root = characterParts(self.Player)
        if humanoid then humanoid:MoveTo(root.Position) end
    end
    self.AutoMoving = false
end
function Extension:SetAutoPlay(enabled)
    if not self.Settings then return end
    enabled = enabled == true
    if self.Settings.AutoPlay == enabled then return end
    self.Settings.AutoPlay = enabled
    if self.AutoPlayToggle and type(self.AutoPlayToggle.SetValue) == "function" then
        pcall(self.AutoPlayToggle.SetValue, enabled)
    end
    if enabled then
        self.RunSerial=(self.RunSerial or 0)+1
        self.NextTrace=nil
        -- Auto-play defends on its own, so Blessed's Auto Guard is switched
        -- off (one movement writer) and restored when Auto-play stops.
        self.AutoPlaySnapshot, self.AutoPlayApplied = {}, {}
        for name, value in pairs({Aimbot=true, AutoGuard=false, BallMagnet=true, BallReach=true}) do
            self.AutoPlaySnapshot[name] = self.Settings[name]
            self.AutoPlayApplied[name] = value
            self:SetFeature(name, value)
        end
        self.AutoPlayStarted, self.State, self.StateSince = self.Clock, nil, self.Clock
        self.AutoPlayStatus = "Experimental: scanning"
        if self.LockMatch then self:LockMatch() end
        self:Log("toggle", "Auto-play enabled (Auto Guard off)")
    else
        if self.ResetOffense then self:ResetOffense() end
        self:StopAutoMove()
        for name, value in pairs(self.AutoPlaySnapshot or {}) do
            -- Restore only values that still match the ones Auto-play applied.
            if self.Settings[name] == (self.AutoPlayApplied or {})[name] then self:SetFeature(name, value) end
        end
        self.AutoPlaySnapshot, self.AutoPlayApplied, self.AutoPlayStatus = nil, nil, "Off"
        self.State, self.PendingState = "Off", nil
        self.StateSince,self.Holder,self.StopReason=self.Clock,nil,"Auto-play disabled"
        self.PreparingShot,self.ProtectFacing=false,false
        self:Log("toggle", "Auto-play disabled (Auto Guard restored)")
    end
end
function Extension:LooseBall(root)
    local nearest, best = nil, 50
    for part in pairs(self:BallSet()) do
        if part.Parent and not self:BallOwner(part) then
            local d = distance(root.Position, part.Position)
            if d < best then nearest, best = part, d end
        end
    end
    return nearest
end
function Extension:InShotRange(root)
    local high = self.Settings.AimbotType == "High"
    local minimum, maximum = high and 57 or 58, (high or self.Settings.AimbotType=="Mixed arc") and 73 or 74
    local goals = self.Goals and self:Goals() or self.Collection:GetTagged("FieldGoals")
    for _, goal in ipairs(goals) do
        if goal:IsA("BasePart") then
            local d = distance(root.Position, goal.Position)
            if d >= minimum and d < maximum then return true end
        end
    end
    return false
end
local function isTeammate(self, player)
    return self.Player.Team ~= nil and player.Team == self.Player.Team
        and self.Player.Neutral == false and player.Neutral == false
end
-- Raw possession read: who holds the ball right now.
function Extension:ReadPossession(character)
    return self:SelectMatchHolder(character)
end
-- Explicit state with debouncing so brief reparenting during a dribble or a
-- delayed replication does not flip offense/defense.
function Extension:UpdateState(character, humanoid, root)
    local now = self.Clock
    local state, holder, reason
    local last = self.LastRootPosition
    self.LastRootPosition = root.Position
    if last and (root.Position-last).Magnitude > 25 then
        self.ResetUntil = now+0.6
        self:Log("reset", string.format("teleport %.0f studs (score/reset or respawn)", (root.Position-last).Magnitude))
    end
    local busy = self.Shooting or (self.AimDepth or 0) > 0
    if self:IsManual() then state, reason = "Manual", tostring(self.ManualReason or "input")
    elseif self.ResetUntil and now < self.ResetUntil then state, reason = "Reset", "position reset"
    elseif busy then state, reason = "Shot", self.Shooting and "shot routine" or ((self.AimDepth or 0) > 0 and "aim routine" or "dunk")
    else
        local raw, who = self:ReadPossession(character)
        local committed = self.State
        if raw == committed or committed == nil or committed == "Manual" or committed == "Reset" or committed == "Shot" or committed == "Off" then
            state, holder = raw, who
            self.PendingState = nil
        else
            -- Leaving our own possession needs longer confirmation (dribble
            -- reparenting); other changes confirm quickly.
            -- A confirmed opponent holder is acted on quickly (steal); a ball
            -- briefly out of our container waits longer (dribble reparent).
            local hold = (committed == "Own" and raw == "Loose") and 0.3 or (raw == "Loose" and 0.25 or 0.12)
            if self.PendingState ~= raw then self.PendingState, self.PendingSince = raw, now end
            if now-self.PendingSince >= hold then state, holder = raw, who; self.PendingState = nil
            else state, holder = committed, self.Holder end
        end
        reason = holder and holder.Name or "ball"
    end
    if state ~= self.State then
        self:Log("state", tostring(self.State).." -> "..state.." ("..tostring(reason)..")")
        self.LastTransition = tostring(self.State).."->"..state.." ("..tostring(reason)..")"
        local was = self.State
        self.State, self.StateSince = state, now
        if was == "Own" and state ~= "Shot" and self.ResetOffense then self:ResetOffense() end
        if state ~= "Opponent" then self.DefenseGoal, self.LastDefenseTarget, self.DefenseFacing = nil, nil, nil end
        if state ~= "Own" and state ~= "Shot" then self.ShotSpot = nil end
        self.AutoMovePoint = nil
    end
    self.Holder = holder
    return state, holder
end
function Extension:AutoPlayStep(character, humanoid, root)
    local state, holder = self:UpdateState(character, humanoid, root)
    if state == "Manual" then
        if self.ResetOffense and self.OffenseCharacter then self:ResetOffense() end
        self:StopAutoMove(); self.StopReason = "manual input ("..tostring(self.ManualReason)..")"
        self.AutoPlayStatus = "Paused: manual input"; return
    end
    if state == "Reset" then
        if self.ResetOffense and self.OffenseCharacter then self:ResetOffense() end
        self:StopAutoMove(); self.StopReason = "dead ball / reset"; self.AutoPlayStatus = "Reset: waiting"; return
    end
    if state == "Shot" then self.StopReason = "shot/dunk in progress"; return end
    if state == "Opponent" then
        if self.ResetOffense and self.OffenseCharacter then self:ResetOffense() end
        self:DefenseStep(character, humanoid, root, holder)
        self.StopReason = self.AutoMovePoint and nil or self.DefenseIntent
        self.AutoPlayStatus = "Defense: "..tostring(self.DefenseIntent); return
    end
    if state == "Teammate" then
        if self.ResetOffense and self.OffenseCharacter then self:ResetOffense() end
        self:StopAutoMove(); self.StopReason = "teammate has the ball"; self.AutoPlayStatus = "Teammate possession"; return
    end
    if state == "Own" and not heldBall(character) then
        -- Possession change still being confirmed: do not run offense
        -- without the ball; keep still until the state settles.
        self:StopAutoMove(); self.StopReason = "confirming possession"; return
    end
    if state == "Own" then
        self:ClearTarget()
        if self.OffenseStep and not self:OffenseStep(character, humanoid, root) then return end
        self:StopAutoMove()
        self.AutoPlayStatus = "Open shot: settling"
        if self.Settings.Aimbot and self.AimAction and not self.Shooting and self.Clock - self.LastShot >= 1.25 and self:InShotRange(root) then
            self.Shooting, self.LastShot, self.AutoPlayStatus = true, self.Clock, "Shooting (experimental)"
            self.Environment.task.spawn(function()
                local function valid()
                    return self.Alive and self.Settings.AutoPlay and not self:IsManual() and self.Player.Character == character
                        and humanoid.Health > 0 and heldBall(character) and self:InShotRange(root)
                        and (not self.CanTakeShot or self:CanTakeShot(root))
                end
                local ok, message = pcall(function()
                    if not valid() then return end
                    self.ShotAttempt = {Valid=valid, Dispatched=false}
                    local goalAtShot=self.OffenseGoal
                    local attempt=self.ShotAttempt
                    self.ShotAttempts=(self.ShotAttempts or 0)+1
                    self.AutoJumpSuppressUntil=self.Clock+0.7
                    self.AutoPlayStatus = "Jumping for shot"
                    -- JumpRequest starts Blessed's delayed shot BEFORE takeoff.
                    -- Schedule that same routine independently of jump detection.
                    attempt.Dispatched=true
                    self.Environment.task.spawn(function()
                        local shotOK,shotError=pcall(function()
                            if attempt.Valid() then
                                self.AimDepth=(self.AimDepth or 0)+1
                                local aimOK,aimError=pcall(self.AimAction)
                                self.AimDepth=math.max(0,self.AimDepth-1)
                                if not aimOK then error(aimError,0) end
                                attempt.Ran=true
                                -- Verify from the routine's own completion; the
                                -- original yields for ShotDelay before clicking.
                                if self.StartShotTrack then self:StartShotTrack("Shot", character, self.OffenseGoal or goalAtShot, nil) end
                            end
                        end)
                        attempt.Completed=true
                        if not shotOK then attempt.Error=tostring(shotError) end
                    end)
                    local jumped=self:RequestAutoJump(humanoid,root,valid)
                    self.LastJumpConfirmed=jumped
                    for _=1,40 do
                        if attempt.Completed or not self.Alive then break end
                        self.Environment.task.wait(0.025)
                    end
                    if attempt.Error then error(attempt.Error) end
                    self.LastShotResult=jumped and "Shot routine sent with jump" or "Shot routine sent; jump unconfirmed"

                    self.AutoPlayStatus=self.LastShotResult
                end)
                if not ok then
                    self.LastShotResult = "Shot error: " .. tostring(message)
                    self.AutoPlayStatus = self.LastShotResult
                end
                if self.ReleaseJumpKey then self:ReleaseJumpKey() end
                self.ShotAttempt = nil
                self.Shooting = false
            end)
        end
    else
        if self.ResetOffense and self.OffenseCharacter then self:ResetOffense() end
        self:RecoveryStep(character,humanoid,root)
    end
end
function Extension:Tick(dt)
    if not self.Alive or not self.Settings then return end
    self.Clock = self.Clock + math.max(0, math.min(dt, 0.5))
    if self.ReleaseDribbleKeys then self:ReleaseDribbleKeys(false) end
    if self.ShotTrack and self.TrackShot then self:TrackShot() end
    self:CaptureTrace()
    self.TickAccumulator = (self.TickAccumulator or 0) + dt
    -- Faster decisions when an attacker is close; 10 Hz otherwise.
    if self.TickAccumulator < (self.PlanInterval or 0.1) then return end
    self.TickAccumulator = 0
    self.PlanCount = (self.PlanCount or 0)+1
    self:Watchdogs()
    if self.Settings.PlayerCollisions and self.UpdatePlayerCollisions then self:UpdatePlayerCollisions() end
    local character, humanoid, root = characterParts(self.Player)
    if not humanoid then
        if self.ResetOffense then self:ResetOffense() end
        if self.ShotTrack and self.FinishShotTrack then self:FinishShotTrack("Cancelled: character died/reset") end
        if self.State ~= "Dead" and self.Settings.AutoPlay then self:Log("state", tostring(self.State).." -> Dead"); self.State = "Dead" end
        self.Shooting, self.ShotAttempt, self.AimDepth, self.DunkingUntil = false, nil, 0, nil
        self:ClearTarget(); self:StopAutoMove(); self.AutoPlayStatus = "Waiting for respawn"; return
    end
    self:WatchCharacter(character, humanoid)
    if (self.Settings.AutoGuard or self.Settings.AutoPlay) and self.Selector and not heldBall(character) and not self:IsManual() then
        self:SelectTarget(self.Selector())
    else self:ClearTarget() end
    if self.Settings.AutoPlay then self:AutoPlayStep(character, humanoid, root) end
end
-- Bounded recovery for confirmed stale internal state. Genuine game actions
-- and manual input are not overridden.
function Extension:Watchdogs()
    local now = self.Clock
    if self.Shooting then
        self.ShootingSince = self.ShootingSince or now
        if now-self.ShootingSince > 4 then
            self:Log("watchdog", "shot routine flag stuck 4s: cleared")
            self.Shooting, self.ShotAttempt = false, nil
        end
    else self.ShootingSince = nil end
    if (self.AimDepth or 0) > 0 then
        self.AimSince = self.AimSince or now
        if now-self.AimSince > 5 then self:Log("watchdog", "aim depth stuck 5s: cleared"); self.AimDepth = 0 end
    else self.AimSince = nil end
    -- Stalled movement: a destination we are not approaching.
    local _, humanoid, root = characterParts(self.Player)
    if root and self.AutoMovePoint and self.Settings.AutoPlay then
        local away = (self.AutoMovePoint-root.Position).Magnitude
        if not self.StallPosition or (root.Position-self.StallPosition).Magnitude > 0.5 then
            self.StallPosition, self.StallSince = root.Position, now
        elseif away > 3 and now-self.StallSince > 2 then
            self:Log("watchdog", string.format("movement stalled %.1fs, %.0f studs from target: re-issued", now-self.StallSince, away))
            self.LastMoveToPoint, self.StallSince = nil, now
        end
    else self.StallPosition = nil end
    local close = self.State == "Opponent" and self.Holder and characterParts(self.Holder)
    local _, _, holderRoot = characterParts(self.Holder)
    self.PlanInterval = (close and root and holderRoot and (holderRoot.Position-root.Position).Magnitude < 18) and 0.05 or 0.1
end
-- Death/knockdown instrumentation (the recording shows bodies breaking apart;
-- the cause is not visible on video).
function Extension:WatchCharacter(character, humanoid)
    if self.WatchedCharacter == character then return end
    for _, connection in ipairs(self.CharacterConnections or {}) do disconnect(connection) end
    self.CharacterConnections, self.WatchedCharacter = {}, character
    if humanoid.Died then
        self.CharacterConnections[1] = humanoid.Died:Connect(function()
            self:Log("character", "Humanoid died (action="..tostring(self.GameAction and self:GameAction(character))..")")
        end)
    end
    if humanoid.StateChanged then
        self.CharacterConnections[2] = humanoid.StateChanged:Connect(function(_, new)
            local name = tostring(new)
            if name:find("Physics") or name:find("Ragdoll") or name:find("FallingDown") or name:find("Dead") or name:find("PlatformStanding") then
                self:Log("character", "state "..name)
            end
        end)
    end
end
function Extension:StatusText()
    local now=self.Clock
    local function name(player) return player and player.Name or "-" end
    local character=self.Player and self.Player.Character
    local action=self.GameAction and self:GameAction(character)
    local manual=self.Clock<(self.ManualUntil or 0) and string.format("%s %.1fs", tostring(self.ManualReason), self.ManualUntil-now) or "none"
    local _,_,root=characterParts(self.Player)
    local moveDistance=root and self.AutoMovePoint and distance(root.Position,self.AutoMovePoint)
    local moveContext=moveDistance and string.format(" | target %.1f studs away",moveDistance) or ""
    local lines={
        string.format("State %s for %.1fs | %s", tostring(self.State or "-"), now-(self.StateSince or now), self.LastTransition or "-"),
        "Holder "..name(self.Holder).." | jump target "..name(self.Target),
        "Court "..self:GoalLabel(self.MatchGoal).." | opponent "..name(self.MatchOpponent),
        "Context "..tostring(self.ContextReason or "-").." | "..tostring(self.CameraControlStatus or "camera idle"),
        "Basket "..tostring((self.State=="Opponent" and self.DefenseGoal or self.OffenseGoal) and (self.State=="Opponent" and self.DefenseGoal or self.OffenseGoal).Name or "-")
            .." | intent "..tostring(self.State=="Opponent" and self.DefenseIntent or self.AutoPlayStatus),
        "Stopped: "..tostring(self.AutoMovePoint and "moving" or (self.StopReason or "-")).." | manual "..manual..moveContext,
        "Action "..tostring(action).." | shooting "..tostring(self.Shooting==true).." aim "..tostring(self.AimDepth or 0)
            .." dunking "..tostring(self.DunkingUntil~=nil and now<self.DunkingUntil),
        (self.LastShotResult or "No shot yet").." / "..tostring(self.ShotBlockReason or "-"),
        "Shots sent "..tostring(self.ShotAttempts or 0).." released "..tostring(self.ShotsReleased or 0)
            .." near rim "..tostring(self.ShotsNearRim or 0).." | dunks "..tostring(self.DunkAttempts or 0).."/"..tostring(self.DunksStarted or 0)
            .." | contests "..tostring(self.ContestCount or 0),
        "Dribble "..tostring(self.DribbleStatus or "-").." | shield "..tostring(self.ProtectFacing==true).." | setup "..tostring(self.PreparingShot==true),
        "Arc "..tostring(self.Settings.AimbotType).." delay "..tostring(self.Settings.ShotDelay).." | planning "..tostring(self.PlanCount or 0),
        "Last error: "..tostring(self.LastError or "none"),
    }
    local log=self.EventLog or {}
    for k=math.max(1,#log-3),#log do lines[#lines+1]=log[k] end
    return table.concat(lines,"\n")
end
function Extension:Install(environment, settings)
    -- Blessed can initialize a second settings table while choosing its game
    -- branch. Rebind to that table without installing a second event loop.
    if self.Installed then
        self.Settings = settings
        settings.AimbotKeybind = nil
        settings.AutoGuardJumpMatch = UltimatePreferences.MatchTargetJump
        settings.AutoPlay = false
        settings.AutoPlayDribble = true
        settings.AutoPlayBasket = "Nearest"
        settings.PlayerCollisions = false
        settings.AutoPlayKeybind = environment.Enum.KeyCode.J
        settings.AutoPlayCamera = true
        settings.AutoPlayDunk = true
        return
    end
    self.Installed, self.Environment, self.Settings = true, environment, settings
    self.Players = environment.game:GetService("Players")
    self.Player = self.Players.LocalPlayer
    self.Input = environment.game:GetService("UserInputService")
    self.Run = environment.game:GetService("RunService")
    self.Collection = environment.game:GetService("CollectionService")
    settings.AimbotKeybind = nil
    settings.AutoGuardJumpMatch = UltimatePreferences.MatchTargetJump
    settings.AutoPlay = false
    settings.AutoPlayDribble = true
    settings.AutoPlayBasket = "Nearest"
    settings.PlayerCollisions = false
    settings.AutoPlayKeybind = environment.Enum.KeyCode.J
    settings.AutoPlayCamera = true
    settings.AutoPlayDunk = true
    self:Connect(self.Run.Heartbeat, function(dt)
        local ok, message = pcall(self.Tick, self, dt)
        if not ok then
            -- Recover from a single bad frame; only repeated errors disable.
            self.LastError = tostring(message)
            self:Log("error", self.LastError)
            self:StopAutoMove()
            if self.ResetOffense then pcall(self.ResetOffense, self) end
            self.ErrorTimes = self.ErrorTimes or {}
            local times = self.ErrorTimes
            times[#times+1] = self.Clock
            while times[1] and self.Clock-times[1] > 10 do table.remove(times, 1) end
            if #times >= 5 then
                self:SetAutoPlay(false)
                self.AutoPlayStatus = "Paused after repeated errors: " .. tostring(message)
            else self.AutoPlayStatus = "Recovered from error: " .. tostring(message) end
        end
    end)
    self.RenderName = "UltimateAutoPlay_" .. tostring(self)
    self.Run:BindToRenderStep(self.RenderName, environment.Enum.RenderPriority.Camera.Value + 1, function(dt)
        if self.UpdateAutoFacing then
            local ok=pcall(self.UpdateAutoFacing,self,dt or 1/60)
            if not ok and self.ReleaseAutoFacing then self:ReleaseAutoFacing() end
        end
        if self.Alive and self.Settings.AutoPlay and self.AutoMovePoint and not self:IsManual() then
            local character, humanoid, root = characterParts(self.Player)
            local action = humanoid and self.GameAction and self:GameAction(character)
            if (action == "Shooting" or action == "Dunking") and not self.FreezeLogged then
                self:StopAutoMove()
            elseif humanoid and not self.Shooting then
                -- Re-issue MoveTo only when the target meaningfully changes
                -- (or to refresh Roblox's 8 s MoveTo timeout).
                local last = self.LastMoveToPoint
                if not self.AutoMoving or self.LastMoveToHumanoid ~= humanoid or not last
                    or (last-self.AutoMovePoint).Magnitude > 0.4 or self.Clock-(self.LastMoveToTime or -100) > 1 then
                    humanoid:MoveTo(self.AutoMovePoint); self.AutoMoving = true
                    self.LastMoveToPoint, self.LastMoveToTime, self.LastMoveToHumanoid = self.AutoMovePoint, self.Clock, humanoid
                end
                local ball = (self.State == "Own" or self.State == nil) and heldBall(character)
                if self.ChooseDribble and ball then
                    pcall(self.ChooseDribble,self,root,self.AutoMovePoint,self.OpponentReads or {},ball)
                end
            end
        end
    end)
end
function Extension:InstallControls(section)
    if self.ControlsInstalled or not self.Settings then return end
    self.ControlsInstalled = true
    section:NewToggle({Title = "Match target jump", Default = true, Callback = function(value)
        self.Settings.AutoGuardJumpMatch = value
    end})
    self.AutoPlayToggle = section:NewToggle({Title = "Auto-play", Default = false, Callback = function(value)
        self:SetAutoPlay(value)
    end})
    section:NewKeybind({Title = "Auto-play key", Default = self.Settings.AutoPlayKeybind, Hold = false, Callback = function(value)
        self.Settings.AutoPlayKeybind = value
    end})
    section:NewToggle({Title = "Auto-play dribble", Default = true, Callback = function(value)
        self.Settings.AutoPlayDribble = value
        if not value and self.ReleaseDribbleKeys then self:ReleaseDribbleKeys(true) end
    end})
    section:NewToggle({Title = "Auto-play camera", Default = true, Callback = function(value)
        self.Settings.AutoPlayCamera=value
        if not value and self.ReleaseAutoFacing then self:ReleaseAutoFacing() end
    end})
    section:NewToggle({Title = "Auto-dunk", Default = true, Callback = function(value)
        self.Settings.AutoPlayDunk=value
    end})
    section:NewButton({Title = "Shot status", Callback = function()
        local captures=self.InputCaptures
        if captures and captures[2] and type(captures[2].Notification)=="function" then
            pcall(function()
                captures[2].Notification().new({Title="Auto-play status",Description=self:StatusText(),Duration=10})
            end)
        end
    end})
    section:NewButton({Title = "Copy Auto-play log", Callback = function()
        local counts={};for key,count in pairs(self.MoveCounts or {})do counts[#counts+1]=key.."="..count end;table.sort(counts)
        local text=self:StatusText().."\nMoves "..table.concat(counts,", ").."\n--- events ---\n"..table.concat(self.EventLog or {},"\n")
            .."\n--- tactical trace (0.5s samples, latest 60s) ---\n"..table.concat(self.TraceLog or {},"\n")
        local copy=self.Environment.setclipboard or self.Environment.toclipboard
        if type(copy)=="function" then pcall(copy,text) end
        self.LastLogCopy=text
    end})
    section:NewDropdown({Title = "Attack basket", Data = {"Nearest", "Second nearest"}, Default = "Nearest", Callback = function(value)
        self.Settings.AutoPlayBasket = value
        if self.ResetOffense then self:ResetOffense() end
    end})
    local names={"Auto (this court)"}
    for _,player in ipairs(self:PlayerList()) do if player~=self.Player then names[#names+1]=player.Name end end
    section:NewDropdown({Title="Opponent",Data=names,Default="Auto (this court)",Callback=function(value)
        self.Settings.AutoPlayOpponent=value;self.MatchOpponent=nil
    end})
    section:NewButton({Title="Lock court here",Callback=function() self:LockMatch() end})
    section:NewButton({Title="Lock viewed hoop",Callback=function() self:LockViewedHoop() end})
    section:NewToggle({Title = "Player collisions", Default = false, Callback = function(value)
        self:SetPlayerCollisions(value)
    end})
end
-- Local torso contact only. No impulses, velocity changes, or ownership calls.
function Extension:RestoreCollisionPart(part, record)
    for key, saved in pairs(record) do
        pcall(function()
            if part[key] == saved.Applied then part[key] = saved.Original end
        end)
    end
end
function Extension:ClearPlayerCollisions()
    for part, record in pairs(self.CollisionParts or {}) do self:RestoreCollisionPart(part, record) end
    self.CollisionParts = {}
end
function Extension:SetPlayerCollisions(enabled)
    if not self.Settings then return end
    self.Settings.PlayerCollisions = enabled == true and self.Alive
    if self.Settings.PlayerCollisions then
        self:UpdatePlayerCollisions()
    else self:ClearPlayerCollisions();self.CollisionStatus = "Off" end
end
function Extension:UpdatePlayerCollisions()
    if not self.Alive or not self.Settings.PlayerCollisions then self:ClearPlayerCollisions();return end
    local character, _, root = characterParts(self.Player)
    local wanted = {}
    if character then
        for _, player in ipairs(self.Players:GetPlayers()) do
            local other, _, otherRoot = characterParts(player)
            if other and (player == self.Player or distance(root.Position,otherRoot.Position) <= 20) then
                for _, name in ipairs({"Torso", "UpperTorso", "LowerTorso"}) do
                    local part = other:FindFirstChild(name)
                    if part and part:IsA("BasePart") and not part.Anchored then wanted[part] = true end
                end
            end
        end
    end
    self.CollisionParts = self.CollisionParts or {}
    for part, record in pairs(self.CollisionParts) do
        if not wanted[part] then self:RestoreCollisionPart(part,record);self.CollisionParts[part] = nil end
    end
    local applied, failed = 0, false
    for part in pairs(wanted) do
        local record = self.CollisionParts[part] or {}
        self.CollisionParts[part] = record
        for key, value in pairs({CanCollide=true, CollisionGroup="Default"}) do
            local ok = pcall(function()
                local current = part[key]
                if not record[key] then record[key] = {Original=current,Applied=value}
                elseif current ~= value then record[key].Original = current end
                if current ~= value then part[key] = value end
            end)
            if not ok then failed = true end
        end
        applied = applied+1
    end
    self.CollisionStatus = failed and "Some local properties unavailable" or (applied > 0 and "Local torso contacts enabled" or "Waiting for character")
end
function Extension:ObserveInstance(target, key, value, environment)
    if key == "Name" and value == "RobloxGameGui" and environment.typeof(target) == "Instance" then
        self.Screen = target
        self:Connect(target.Destroying, function() self:Destroy() end)
    end
end
function Extension:Destroy()
    if not self.Alive then return end
    self:SetAutoPlay(false)
    self:SetPlayerCollisions(false)
    if self.ResetOffense then self:ResetOffense() end
    self:ClearTarget(); self:StopAutoMove()
    self.Alive = false
    for _, connection in ipairs(self.Connections) do disconnect(connection) end
    for _, connection in ipairs(self.CharacterConnections or {}) do disconnect(connection) end
    self.CharacterConnections, self.WatchedCharacter = {}, nil
    self.Connections = {}
    if self.Run and self.RenderName then self.Run:UnbindFromRenderStep(self.RenderName) end
end
customizeClosure = function(name, original, environment, captures)
    if name == "root.1083.232.12.644" then
        return function(section, config, ...)
            if type(config)=="table" and config.Title=="Type" and type(config.Data)=="table" then
                local low,high=false,false
                for _,value in ipairs(config.Data) do low=low or value=="Low";high=high or value=="High" end
                if low and high then config.Data={"Low","Mixed arc","High"} end
            end
            return original(section,config,...)
        end
    elseif name == "root.175" then
        return function(...)
            local settings=captures[0]
            if not settings or settings.AimbotType~="Mixed arc" then return original(...) end
            local player=environment.game.Players.LocalPlayer
            local previousPower=player:GetAttribute("Power")
            local args=table.pack(...)
            local ok,result,power=pcall(function()
                settings.AimbotType="Low"
                local low=original(table.unpack(args,1,args.n))
                local lowPower=player:GetAttribute("Power")
                settings.AimbotType="High"
                local high=original(table.unpack(args,1,args.n))
                local highPower=player:GetAttribute("Power")
                assert(type(low)=="number" and type(high)=="number","Arc endpoint unavailable")
                local midPower=type(lowPower)=="number" and type(highPower)=="number" and (lowPower+highPower)/2 or previousPower
                return (low+high)/2,midPower
            end)
            settings.AimbotType="Mixed arc"
            player:SetAttribute("Power",ok and power or previousPower)
            if not ok then error(result,0) end
            return result
        end
    elseif name == "root.2169" then
        Extension.InputCaptures = captures
        return function(input, processed) return Extension:GuardKey(input, processed, captures) end
    elseif name == "root.2115" then
        Extension.Selector = original
        return function(...)
            local player = original(...)
            if Extension.Installed then Extension:SelectTarget(player) end
            return player
        end
    elseif name == "root.106" then
        Extension.AimAction = original
        return function(...)
            -- Let the normal JumpRequest path keep its original ShotDelay timing.
            -- Claim once; the queued fallback must not issue a duplicate shot.
            if Extension.Shooting and Extension.Settings and Extension.Settings.AutoPlay then
                local attempt=Extension.ShotAttempt
                if not attempt or attempt.Dispatched or not attempt.Valid() then return end
                attempt.Dispatched=true
                Extension.AimDepth=(Extension.AimDepth or 0)+1
                local ok,message=pcall(original,...)
                Extension.AimDepth=math.max(0,Extension.AimDepth-1)
                attempt.Ran=ok or nil
                attempt.Completed=true
                if not ok then attempt.Error=tostring(message) end
                return
            end
            if Extension.Settings and Extension.Settings.AutoPlay and Extension.AutoJumpSuppressUntil
                and Extension.Clock < Extension.AutoJumpSuppressUntil then return end
            -- Manual Space shot: keep the camera assist off the camera while
            -- the original routine aims it (it saves, aims, clicks, restores).
            Extension.AimDepth=(Extension.AimDepth or 0)+1
            if Extension.ReleaseAutoFacing then pcall(Extension.ReleaseAutoFacing, Extension) end
            local results=table.pack(pcall(original,...))
            Extension.AimDepth=math.max(0,Extension.AimDepth-1)
            if not results[1] then error(results[2],0) end
            return table.unpack(results,2,results.n)
        end
    elseif name == "root.2138" then
        return function(...)
            if Extension.Installed and Extension:IsManual() then Extension:ClearTarget(); return end
            if Extension.Installed and Extension.Settings and Extension.Settings.AutoPlay then return end
            return original(...)
        end
    end
    return original
end
local function observeUltimateRoot(environment, registers, pc)
    local settings = registers[15]
    if (not Extension.Installed or Extension.Settings ~= settings) and type(settings) == "table" and settings.AutoGuardKeybind ~= nil
        and settings.AntiDrop ~= nil and settings.BallMagnetStrength ~= nil then
        Extension:Install(environment, settings)
    end
    if pc == 1213 and Extension.Installed then Extension:InstallControls(registers[23]) end
end

-- Experimental possession planner. Reads current replicated positions/velocities;
-- it does not know opponents' future inputs or the game's court/team rules.
local function flat(v) return Extension.Environment.Vector3.new(v.X, 0, v.Z) end
local function unit(v)
    local length = v.Magnitude
    if length < 0.001 then return Extension.Environment.Vector3.new(1, 0, 0) end
    return v / length
end
local function rotate(v, angle)
    local c, s = math.cos(angle), math.sin(angle)
    return Extension.Environment.Vector3.new(v.X*c-v.Z*s, 0, v.X*s+v.Z*c)
end
-- Roblox RightVector for a horizontal look direction.
local function lateralOf(forward) return Extension.Environment.Vector3.new(-forward.Z, 0, forward.X) end
local function segmentDistance(point, a, b)
    local d = flat(b-a)
    local t = math.max(0, math.min(1, flat(point-a):Dot(d) / math.max(0.001, d:Dot(d))))
    return flat(point-(a+d*t)).Magnitude
end
local function ballPart(ball)
    if not ball then return nil end
    if ball:IsA("BasePart") then return ball end
    return ball:FindFirstChildWhichIsA("BasePart")
end
-- Hoopz marks the character's current Action ("Shooting", "Dunking", ...).
local function gameAction(character)
    if not character or type(character.GetAttribute) ~= "function" then return nil end
    local ok, value = pcall(character.GetAttribute, character, "Action")
    return ok and value or nil
end
Extension.GameAction = function(_, character) return gameAction(character) end

---------------------------------------------------------------------------
-- Shared caches (each read was previously repeated per frame / per call).
---------------------------------------------------------------------------
function Extension:PlayerList()
    if not self.PlayerCache or self.Clock-self.PlayerCacheTime >= 0.5 or self.Clock < self.PlayerCacheTime then
        self.PlayerCache, self.PlayerCacheTime = self.Players:GetPlayers(), self.Clock
    end
    return self.PlayerCache
end
function Extension:Goals()
    local cache = self.GoalCache
    local stale = not cache or self.Clock-self.GoalCacheTime >= 2 or self.Clock < self.GoalCacheTime
    if not stale then for _, goal in ipairs(cache) do if not goal.Parent then stale = true; break end end end
    if stale then
        cache = {}
        for _, goal in ipairs(self.Collection:GetTagged("FieldGoals")) do
            if goal:IsA("BasePart") then cache[#cache+1] = goal end
        end
        self.GoalCache, self.GoalCacheTime = cache, self.Clock
    end
    return cache
end
function Extension:MakeRayParams()
    local env = self.Environment
    if not env.RaycastParams or not env.workspace.Raycast then return nil end
    if self.RayParamsCache and self.Clock-self.RayParamsTime < 1 and self.Clock >= self.RayParamsTime then
        return self.RayParamsCache
    end
    local params = env.RaycastParams.new()
    params.FilterType = env.Enum.RaycastFilterType.Exclude
    local exclude = {}
    for _, player in ipairs(self:PlayerList()) do
        if player.Character then exclude[#exclude+1] = player.Character end
    end
    params.FilterDescendantsInstances, params.IgnoreWater, params.RespectCanCollide = exclude, false, true
    self.RayParamsCache, self.RayParamsTime = params, self.Clock
    return params
end
-- Event-driven ball index: one initial scan, then DescendantAdded. Replaces a
-- full workspace:GetDescendants() every second while looking for loose balls.
local function isBallPart(part)
    return part and part:IsA("BasePart") and (part.Name == "Ball" or part.Name == "Basketball")
end
function Extension:BallSet()
    local workspace = self.Environment.workspace
    local listening = self.BallListening
    if not self.BallIndex or (not listening and self.Clock-(self.BallScanTime or -100) >= 3) then
        self.BallIndex = self.BallIndex or {}
        for _, part in ipairs(workspace:GetDescendants()) do
            if isBallPart(part) then self.BallIndex[part] = true end
        end
        self.BallScanTime = self.Clock
        if not listening and workspace.DescendantAdded then
            self.BallListening = true
            self:Connect(workspace.DescendantAdded, function(part)
                if isBallPart(part) then self.BallIndex[part] = true end
            end)
        end
    end
    for part in pairs(self.BallIndex) do
        if not part.Parent then self.BallIndex[part] = nil end
    end
    return self.BallIndex
end
function Extension:BallOwner(part)
    for _, player in ipairs(self:PlayerList()) do
        if player.Character and part:IsDescendantOf(player.Character) then return player end
    end
    return nil
end

---------------------------------------------------------------------------
-- Inputs
---------------------------------------------------------------------------
function Extension:ReleaseDribbleKeys(all)
    for key, deadline in pairs(self.DribbleKeys or {}) do
        if all or self.Clock >= deadline then
            if self.VirtualInput then pcall(self.VirtualInput.SendKeyEvent, self.VirtualInput, false, key, false, self.Environment.game) end
            self.DribbleKeys[key] = nil
        end
    end
end
function Extension:ResetOffense()
    self:ReleaseDribbleKeys(true)
    if self.Environment then self:ReleaseJumpKey() end
    if self.ReleaseAutoFacing then self:ReleaseAutoFacing() end
    self.OffenseGoal, self.OffenseCharacter, self.ShotSpot, self.SpotScore = nil, nil, nil, nil
    self.OpenSince, self.ProgressPosition, self.ProgressTime, self.StuckUntil = nil, nil, nil, nil
    self.LastPlan = nil
    self.RouteDirection, self.RouteHoldUntil = nil, nil
    self.SettlePosition,self.SettleSince=nil,nil
    self.DunkMode, self.DriveUntil, self.DunkingUntil = nil, nil, nil
    self.Plan, self.EscapeCount, self.NextEscape, self.PossessionStart = nil, 0, nil, nil
    self.DribbleDecisionUntil=nil
    self.PreparingShot=false
    self.FakeShotStart, self.ForceShot, self.AttackMode = nil, nil, nil
    self.FreezeSince, self.FreezeLogged = nil, nil
end
function Extension:ReleaseJumpKey()
    if not self.Environment then return end
    if self.ExecutorJumpHeld then
        if type(self.Environment.keyrelease)=="function" then pcall(self.Environment.keyrelease,0x20) end
        self.ExecutorJumpHeld=false
    end
    local key = self.Environment.Enum.KeyCode.Space
    if self.DribbleKeys and self.DribbleKeys[key] then
        if self.VirtualInput then pcall(self.VirtualInput.SendKeyEvent,self.VirtualInput,false,key,false,self.Environment.game) end
        self.DribbleKeys[key] = nil
    end
end
function Extension:RequestAutoJump(humanoid, root, valid)
    humanoid.Jump = true
    local states = self.Environment.Enum.HumanoidStateType
    if states and type(humanoid.ChangeState) == "function" then
        pcall(humanoid.ChangeState,humanoid,states.Jumping)
    end
    -- Use the game's normal jump input too; some character controllers consume
    -- or overwrite the Jump property before the next simulation step.
    if not self.Input:IsKeyDown(self.Environment.Enum.KeyCode.Space) then
        if type(self.Environment.keypress)=="function" and type(self.Environment.keyrelease)=="function" then
            self.ExecutorJumpHeld=true
            local ok=pcall(self.Environment.keypress,0x20)
            if not ok then self.ExecutorJumpHeld=false end
            self.Environment.task.delay(0.12,function() self:ReleaseJumpKey() end)
        end
        if not self.VirtualInput then
            local ok, service = pcall(self.Environment.game.GetService,self.Environment.game,"VirtualInputManager")
            if ok then self.VirtualInput=service end
        end
        if self.VirtualInput then
            local key = self.Environment.Enum.KeyCode.Space
            self.DribbleKeys = self.DribbleKeys or {}
            self.DribbleKeys[key] = self.Clock+0.08
            pcall(self.VirtualInput.SendKeyEvent,self.VirtualInput,true,key,false,self.Environment.game)
            self.Environment.task.delay(0.08,function() self:ReleaseJumpKey() end)
        end
    end
    for _=1,20 do
        if not valid() then self:ReleaseJumpKey();return false end
        if humanoid.FloorMaterial == self.Environment.Enum.Material.Air and root.AssemblyLinearVelocity.Y > 1 then
            self:ReleaseJumpKey();return true
        end
        self.Environment.task.wait(0.025)
    end
    self:ReleaseJumpKey()
    return false
end
function Extension:PulseKey(name, hold, cooldown, force)
    if self:IsManual() or self.Shooting then return false end
    if not force and (not self.Settings.AutoPlayDribble or self.Clock-(self.LastDribble or -100) < 0.1) then return false end
    local key = self.Environment.Enum.KeyCode[name]
    self.MoveCooldowns = self.MoveCooldowns or {}
    if self.Clock-(self.MoveCooldowns[name] or -100) < cooldown then return false end
    if key == self.Settings.AutoGuardKeybind or key == self.Settings.AutoPlayKeybind then return false end
    if self.Input:IsKeyDown(key) then return false end
    if not self.VirtualInput then
        local ok, service = pcall(self.Environment.game.GetService,self.Environment.game,"VirtualInputManager")
        if not ok or not service then self.DribbleStatus="Input unavailable";return false end
        self.VirtualInput = service
    end
    self.DribbleKeys = self.DribbleKeys or {}
    self.DribbleKeys[key] = self.Clock+hold
    local ok = pcall(self.VirtualInput.SendKeyEvent,self.VirtualInput,true,key,false,self.Environment.game)
    if not ok then self:ReleaseDribbleKeys(true);self.DribbleStatus="Input unavailable";return false end
    self.LastDribble,self.DribbleStatus,self.LastMove = self.Clock,name,name
    self.MoveCounts=self.MoveCounts or {};self.MoveCounts[name]=(self.MoveCounts[name] or 0)+1
    self.MoveCooldowns[name] = self.Clock
    -- Release independently of the planner too, even if its heartbeat stops.
    self.Environment.task.delay(hold+0.005,function()
        if self.DribbleKeys[key] then
            pcall(self.VirtualInput.SendKeyEvent,self.VirtualInput,false,key,false,self.Environment.game)
            self.DribbleKeys[key]=nil
        end
    end)
    return true
end
function Extension:PulseDribble(name)
    -- Wait (bounded 0.6 s) while Hoopz reports an action from a previous move.
    local action = gameAction(self.Player and self.Player.Character)
    if action=="Shooting" or action=="Dunking" then return false end
    if action ~= nil and action ~= "" then
        if self.ActionSeenValue ~= action then
            self.ActionSeenValue, self.ActionSeenSince = action, self.Clock
            self.ActionsSeen = self.ActionsSeen or {}
            if not self.ActionsSeen[action] then
                self.ActionsSeen[action] = true
                if self.Log then self:Log("action", "Hoopz Action value seen: "..tostring(action)) end
            end
        end
        if self.Clock-(self.ActionSeenSince or self.Clock) < 0.6 then return false end
    else self.ActionSeenValue = nil end
    return self:PulseKey(name, 0.04, name == "R" and 0.4 or 0.2)
end

---------------------------------------------------------------------------
-- World reads
---------------------------------------------------------------------------
function Extension:ReadOpponents(root)
    local result = {}
    self.OpponentMemory=self.OpponentMemory or setmetatable({},{__mode="k"})
    for _, player in ipairs(self:PlayerList()) do
        local sameTeam = self.Player.Team and player.Team == self.Player.Team
            and self.Player.Neutral == false and player.Neutral == false
        if player ~= self.Player and not sameTeam and (not self.MatchGoal or self:MatchPlayer(player)) then
            local character, humanoid, other = characterParts(player)
            if character and math.abs(other.Position.Y-root.Position.Y) < 12
                and flat(other.Position-root.Position).Magnitude < 90 then
                local velocity = flat(other.AssemblyLinearVelocity)
                local previous=self.OpponentMemory[player]
                local elapsed=previous and self.Clock-previous.Time or 0
                if elapsed>=0.06 and elapsed<=0.5 then
                    local measured=flat(other.Position-previous.Position)/elapsed
                    if measured.Magnitude<=45 then velocity=velocity*0.55+measured*0.45 end
                end
                if velocity.Magnitude > 32 then velocity = unit(velocity)*32 end
                if not previous or elapsed>=0.06 or elapsed<0 then
                    self.OpponentMemory[player]={Time=self.Clock,Position=other.Position,Velocity=velocity}
                end
                result[#result+1] = {
                    Player=player, Position=other.Position, Predicted=other.Position+velocity*0.3,
                    Velocity=velocity, Airborne=humanoid.FloorMaterial == self.Environment.Enum.Material.Air
                }
            end
        end
    end
    return result
end
function Extension:HasFloor(position, params)
    if not params then return false end
    local v = self.Environment.Vector3
    local hit = self.Environment.workspace:Raycast(position+v.new(0,2,0), v.new(0,-9,0), params)
    return hit ~= nil and hit.Normal.Y > 0.7 and hit.Material ~= self.Environment.Enum.Material.Water
end
function Extension:WalkClear(a, b, params)
    if not params then return false end
    local delta = flat(b-a)
    local right = rotate(unit(delta), math.pi/2)*1.6
    for _, side in ipairs({-1,0,1}) do
        if self.Environment.workspace:Raycast(a+right*side, delta, params) then return false end
    end
    return self:HasFloor(a+delta*0.5, params) and self:HasFloor(a+delta, params)
end
function Extension:NearestGoal(root, choice)
    local goals = {}
    for _, goal in ipairs(self:Goals()) do
        if goal.Parent and math.abs(goal.Position.Y-root.Position.Y) < 30
            and distance(goal.Position,root.Position) <= 145 then goals[#goals+1] = goal end
    end
    table.sort(goals, function(a,b) return distance(a.Position,root.Position) < distance(b.Position,root.Position) end)
    return goals[choice == "Second nearest" and 2 or 1]
end
-- True when the recovered aimbot (which targets the closest goal) would aim
-- at our chosen basket from this position.
function Extension:GoalIsNearestAt(position, goal)
    local own = (goal.Position-position).Magnitude
    for _, other in ipairs(self:Goals()) do
        if other ~= goal and other.Parent and (other.Position-position).Magnitude < own then return false end
    end
    return true
end
function Extension:SpaceAt(position, opponents)
    local nearest, jumping = 100, false
    for _, opponent in ipairs(opponents) do
        local d = math.min(flat(position-opponent.Position).Magnitude, flat(position-opponent.Predicted).Magnitude)
        nearest = math.min(nearest, d)
        if opponent.Airborne and d < 17 then jumping = true end
    end
    return nearest, jumping
end
function Extension:ShotLaneClear(root, goal, params)
    if not params or not goal then return false end
    -- Conservative straight line to basket; this is not a ballistic simulation.
    local hit = self.Environment.workspace:Raycast(root.Position, goal.Position-root.Position, params)
    self.LastLaneHit = hit
    if hit==nil or hit.Instance==goal then return true end
    -- The goal's rim/backboard can intercept a straight diagnostic ray even
    -- though the recovered shot follows an arc into that same basket.
    return hit.Position and (hit.Position-goal.Position).Magnitude<=5
        and hit.Position.Y>=goal.Position.Y-2
end
function Extension:CanTakeShot(root)
    local goal = self.OffenseGoal
    if not goal or not goal.Parent then self.ShotBlockReason="No attack basket selected";return false end
    if self:NearestGoal(root) ~= goal then self.ShotBlockReason="Selected basket is not the nearest";return false end
    if not self:InShotRange(root) then self.ShotBlockReason="Outside shooting range";return false end
    if not self:ShotLaneClear(root,goal,self:MakeRayParams()) then
        -- After 8 s, a straight-line miss that ends near the hoop (rim/net
        -- structure) no longer blocks; a real wall in between still does.
        local hit=self.LastLaneHit
        if not (self.ForceShot and hit and hit.Position and (hit.Position-goal.Position).Magnitude<=15) then
            self.ShotBlockReason="Shot line blocked";return false
        end
        self.ShotBlockReason="Line hit near the hoop for 8s: shooting anyway"
        return true
    end
    -- Defenders never veto the shot: contested shots go up immediately.
    local space, jumping = self:SpaceAt(root.Position, self.OpponentReads or {})
    self.ShotContested = space < 10 or jumping
    self.ShotBlockReason = self.ShotContested and "Contested: shooting anyway" or "Open and in range"
    return true
end
function Extension:ShotRadius(root, goal)
    local radius3d = self.Settings.AimbotType == "High" and 64 or (self.Settings.AimbotType=="Mixed arc" and 64.5 or 65)
    local dy = goal.Position.Y-root.Position.Y
    return math.sqrt(math.max(1,radius3d*radius3d-dy*dy))
end
function Extension:PickShotSpot(root, opponents, params)
    local goal = self.OffenseGoal
    local radius = self:ShotRadius(root, goal)
    -- Sample around the side we are actually on now, not only the side we
    -- picked the ball up on.
    local base = unit(flat(root.Position-goal.Position))
    local best, score = nil, math.huge
    local function evaluate(position)
        if not self:GoalIsNearestAt(position, goal) then return math.huge end
        if not self:HasFloor(position,params) then return math.huge end
        local space, jumping = self:SpaceAt(position,opponents)
        local travel = flat(position-root.Position).Magnitude
        local cost = travel*0.38 + math.max(0,18-space)*4 + (jumping and 15 or 0)
        for _, opponent in ipairs(opponents) do
            cost = cost + math.max(0,8-segmentDistance(opponent.Predicted,root.Position,position))*2
        end
        if not self:ShotLaneClear({Position=position},goal,params) then cost=cost+60 end
        return cost
    end
    for _, degrees in ipairs({0,-20,20,-40,40,-60,60,-80,80,-110,110}) do
        local position = goal.Position+rotate(base,math.rad(degrees))*radius
        position = self.Environment.Vector3.new(position.X,root.Position.Y,position.Z)
        local cost = evaluate(position)
        if cost < score then best,score=position,cost end
    end
    -- Hysteresis: keep the current spot unless a clearly better one appears.
    if self.ShotSpot and best and flat(self.ShotSpot-best).Magnitude > 3 then
        local current = evaluate(self.Environment.Vector3.new(self.ShotSpot.X,root.Position.Y,self.ShotSpot.Z))
        if current < score + 8 then best, score = self.ShotSpot, current end
    end
    self.ShotSpot,self.SpotScore = best,score
    return best
end
-- Local fan steering with branch-and-bound: costs that need no raycasts are
-- computed first; rays only run for candidates that can still win. The chosen
-- point is identical to evaluating every candidate fully.
function Extension:SteerTo(root, destination, opponents)
    local params = self:MakeRayParams()
    local delta = flat(destination-root.Position)
    if delta.Magnitude < 0.6 then return nil end
    local length = math.min(8,delta.Magnitude)
    local candidates = {}
    for _, degrees in ipairs({0,-30,30,-60,60,-90,90}) do
        local point = root.Position+rotate(unit(delta),math.rad(degrees))*length
        local space = self:SpaceAt(point,opponents)
        local cost = flat(destination-point).Magnitude + math.max(0,10-space)*3
        for _, opponent in ipairs(opponents) do
            cost = cost + math.max(0,5-segmentDistance(opponent.Predicted,root.Position,point))*5
        end
        local direction = unit(point-root.Position)
        if self.RouteDirection and self.RouteHoldUntil and self.Clock < self.RouteHoldUntil then
            cost = cost + (1-direction:Dot(self.RouteDirection))*5
        end
        for _, opponent in ipairs(opponents) do
            if flat(opponent.Position-root.Position).Magnitude < 14 then
                cost = cost + math.max(0,8-flat(point-opponent.Predicted).Magnitude)*2
                local intercept=opponent.Position+opponent.Velocity*math.min(0.5,length/16)
                cost=cost+math.max(0,7-flat(point-intercept).Magnitude)*3
            end
        end
        if self.StuckUntil and self.Clock < self.StuckUntil then
            cost = cost + (degrees == 0 and 30 or 0) + (degrees*(self.EscapeSide or 1) < 0 and 8 or 0)
        end
        candidates[#candidates+1] = {Point=point, Cost=cost}
    end
    table.sort(candidates, function(a,b) return a.Cost < b.Cost end)
    local best, score = nil, math.huge
    for _, candidate in ipairs(candidates) do
        if candidate.Cost >= score then break end
        local point = candidate.Point
        if self:WalkClear(root.Position,point,params) then
            local total = candidate.Cost
            local ahead=point+unit(destination-point)*math.min(4,flat(destination-point).Magnitude)
            if not self:WalkClear(point,ahead,params) then total=total+14 end
            if total < score then best,score=point,total end
        end
    end
    if best then
        if not self.RouteHoldUntil or self.Clock >= self.RouteHoldUntil then self.RouteHoldUntil=self.Clock+0.6 end
        self.RouteDirection=unit(best-root.Position)
    end
    return best
end

---------------------------------------------------------------------------
-- Body and camera: shift-lock style. The body squares toward the attack
-- (rim / drive / escape facing) while the camera sits behind at a constant
-- radius looking up the court. Yaw is rate-limited so it never swings.
---------------------------------------------------------------------------
function Extension:ReleaseAutoFacing()
    local humanoid=self.AutoFacingHumanoid
    if humanoid then
        pcall(function()
            if humanoid.AutoRotate==true then humanoid.AutoRotate=self.SavedAutoRotate end
        end)
    end
    local controller=self.OwnedMouseLock
    self.OwnedMouseLock=nil
    if controller then pcall(function()
        if controller:GetIsMouseLocked() then controller:OnMouseLockToggled() end
    end) end
    self.AutoFacingHumanoid,self.SavedAutoRotate=nil,nil
    self.FaceYaw,self.CameraYaw,self.CameraDistance,self.CameraCurrentDistance=nil,nil,nil,nil
    self.CameraPitch,self.CameraFirstPerson=nil,nil
end
-- Use Roblox's camera controller to rotate the body in shift-lock. Never
-- assign HumanoidRootPart.CFrame: that fights the native movement controller.
function Extension:AcquireMouseLock()
    if self.MouseLockUnavailable and self.Clock<self.MouseLockUnavailable then return false end
    local ok,controller=pcall(function()
        local scripts=self.Player.PlayerScripts or self.Player:FindFirstChild("PlayerScripts")
        local module=scripts and scripts:FindFirstChild("PlayerModule")
        local loader=self.Environment.require or require
        local playerModule=module and loader(module)
        local cameras=playerModule and playerModule:GetCameras()
        return cameras and cameras.activeMouseLockController
    end)
    if not ok or not controller or type(controller.GetIsMouseLocked)~="function"
        or type(controller.OnMouseLockToggled)~="function" then
        self.MouseLockUnavailable=self.Clock+3
        self.CameraControlStatus="Enable native shift-lock manually (controller unavailable)"
        return false
    end
    local success=pcall(function()
        if not controller:GetIsMouseLocked() then controller:OnMouseLockToggled();self.OwnedMouseLock=controller end
    end)
    self.CameraControlStatus=success and "Native shift-lock: camera drives body" or "Native shift-lock unavailable"
    return success
end
-- A camera hit only counts as a wall when it is real, visible, anchored
-- geometry: not the dribbled ball, hitboxes, effects or invisible barriers.
function Extension:IsCameraBlocker(hit)
    local part = hit and hit.Instance
    if not part then return false end
    local ok, blocks = pcall(function()
        if part.Name == "Ball" or part.Name == "Basketball" then return false end
        if part.Transparency > 0.6 or part.Anchored == false then return false end
        local size = part.Size
        if math.max(size.X, size.Y, size.Z) < 4 then return false end
        if part.FindFirstAncestor and part:FindFirstAncestor("Hitboxes") then return false end
        return true
    end)
    if not ok then return true end
    return blocks
end
local atan2 = math.atan2 or math.atan
local function yawOf(d) return atan2(d.X, d.Z) end
local function wrapAngle(a) return (a+math.pi)%(2*math.pi)-math.pi end
local function approachYaw(current, target, rate, maxSpeed, dt)
    if not current then return target end
    dt = math.min(dt, 0.1)
    local step = wrapAngle(target-current)*(1-math.exp(-rate*dt))
    local limit = maxSpeed*dt
    if step > limit then step = limit elseif step < -limit then step = -limit end
    return current + step
end
function Extension:CameraIntervention()
    local env=self.Environment
    local types=env.Enum.UserInputType
    if types and type(self.Input.IsMouseButtonPressed)=="function" then
        for _, button in ipairs({types.MouseButton2}) do
            local ok,down=pcall(self.Input.IsMouseButtonPressed,self.Input,button)
            if ok and down then return true end
        end
    end
    if type(self.Input.GetMouseDelta)=="function" then
        local ok,delta=pcall(self.Input.GetMouseDelta,self.Input)
        if ok and delta and delta.Magnitude>1 then return true end
    end
    return false
end
-- Desired body facing for the current offensive situation.
function Extension:DesiredFacing(root)
    local goal=self.OffenseGoal
    local toGoal=goal and goal.Parent and flat(goal.Position-root.Position)
    local goalDir=toGoal and toGoal.Magnitude>0.5 and unit(toGoal)
    local move=self.AutoMovePoint and flat(self.AutoMovePoint-root.Position)
    local moveDir=move and move.Magnitude>0.6 and unit(move)
    self.ProtectFacing=false
    local owns=heldBall(self.Player and self.Player.Character)
    if self.State=="Opponent" and not owns then return self.DefenseFacing end
    if owns and self.Settings.AutoPlayDribble and not self.DunkMode and not self.PreparingShot then
        local threat,nearest=nil,90
        for _,opponent in ipairs(self.OpponentReads or {})do
            local offset=flat(root.Position-opponent.Predicted)
            local d=offset.Magnitude
            if d>0.1 and d<nearest then threat,nearest=offset,d end
        end
        local away=threat and unit(threat) or (goalDir and goalDir*(-1))
        if away then
            self.ProtectFacing=true
            return unit(away*0.95+(moveDir or away)*0.05)
        end
    end
    local plan=self.Plan
    if plan and plan.Facing then return plan.Facing end
    if not moveDir then return goalDir end
    if not goalDir then return moveDir end
    -- Square up near the rim and while escaping laterally; run with the ball
    -- when moving away from the basket instead of back-pedalling.
    local agreement=moveDir:Dot(goalDir)
    if toGoal.Magnitude<16 then return unit(moveDir+goalDir*3) end
    if agreement < -0.35 then return moveDir end
    return unit(moveDir+goalDir*1.4)
end
function Extension:UpdateAutoFacing(dt)
    local env=self.Environment
    if not env or not env.CFrame or not self.Alive or not self.Settings.AutoPlay or not self.Settings.AutoPlayCamera
        or self.Shooting or (self.AimDepth or 0)>0 or self:IsManual() then self:ReleaseAutoFacing();return end
    local character,humanoid,root=characterParts(self.Player)
    local offense=heldBall(character)
    local defending=not offense and self.State=="Opponent" and self.DefenseFacing~=nil
    if offense and self.Clock-(self.LastShieldRead or -100)>=0.05 then
        self.OpponentReads=self:ReadOpponents(root);self.LastShieldRead=self.Clock
    end
    if not humanoid or not (offense or defending) then self:ReleaseAutoFacing();return end
    local action=gameAction(character)
    if action=="Shooting" or action=="Dunking" then self:ReleaseAutoFacing();return end
    local camera=env.workspace.CurrentCamera
    if camera and env.Enum.CameraType and camera.CameraType==env.Enum.CameraType.Scriptable then
        self:ReleaseAutoFacing();return
    end
    if self:CameraIntervention() then self.CameraPauseUntil=self.Clock+1 end
    -- A camera pause only pauses camera/body assistance; movement continues.
    if self.CameraPauseUntil and self.Clock<self.CameraPauseUntil then self:ReleaseAutoFacing();return end
    local face=self:DesiredFacing(root)
    if not face then self:ReleaseAutoFacing();return end
    if self.AutoFacingHumanoid~=humanoid then
        self:ReleaseAutoFacing();self.AutoFacingHumanoid=humanoid;self.SavedAutoRotate=humanoid.AutoRotate
        local look=root.CFrame and root.CFrame.LookVector
        if look and flat(look).Magnitude>0.1 then self.FaceYaw=yawOf(look) end
    end
    humanoid.AutoRotate=true
    self:AcquireMouseLock()
    self.FaceYaw=approachYaw(self.FaceYaw,yawOf(face),12,9,dt)
    local bodyDir=env.Vector3.new(math.sin(self.FaceYaw),0,math.cos(self.FaceYaw))
    -- Native shift-lock aligns the character with camera yaw.
    if not camera or camera.CameraSubject~=humanoid then self.CameraYaw,self.CameraDistance=nil,nil;return end
    -- Camera orbits the same focus Roblox uses, at YOUR current zoom radius,
    -- so handing control back to the default camera never jumps.
    local focus=root.Position+env.Vector3.new(0,1.5,0)
    if not self.CameraDistance then
        local offset=camera.CFrame.Position-focus
        local radius=offset.Magnitude
        if radius~=radius or radius<2 then self.CameraFirstPerson=true end
        self.CameraDistance=math.max(8,math.min(40,radius==radius and radius or 14))
        self.CameraCurrentDistance=self.CameraDistance
        self.CameraPitch=math.asin(math.max(-0.99,math.min(0.99,offset.Y/math.max(radius,0.001))))
        local look=camera.CFrame.LookVector
        if look and flat(look).Magnitude>0.1 then self.CameraYaw=yawOf(look) end
    end
    if self.CameraFirstPerson then return end
    local viewDir
    if defending then
        -- Defense: keep the attacker in frame from the basket side.
        viewDir=self.DefenseFacing
    else
        local goal=self.OffenseGoal
        local toGoal=goal and goal.Parent and flat(goal.Position-root.Position)
        viewDir=self.ProtectFacing and face or bodyDir
        if not self.ProtectFacing and toGoal and toGoal.Magnitude>8 and unit(toGoal):Dot(bodyDir)>-0.2 then viewDir=unit(bodyDir*0.65+unit(toGoal)*0.35) end
    end
    local quickTurn=defending or self.ProtectFacing
    self.CameraYaw=approachYaw(self.CameraYaw,yawOf(viewDir),quickTurn and 7 or 3,quickTurn and 5.5 or 2.6,dt)
    -- Ease pitch into a court-reading band, never into the floor or overhead.
    local wantPitch=math.max(0.28,math.min(0.6,self.CameraPitch or 0.36))
    self.CameraPitch=(self.CameraPitch or wantPitch)+(wantPitch-(self.CameraPitch or wantPitch))*(1-math.exp(-2*math.min(dt,0.1)))
    local camDir=env.Vector3.new(math.sin(self.CameraYaw),0,math.cos(self.CameraYaw))
    local back=camDir*(-math.cos(self.CameraPitch))+env.Vector3.new(0,math.sin(self.CameraPitch),0)
    local wanted=self.CameraDistance
    local params=self:MakeRayParams()
    local hit=params and env.workspace:Raycast(focus,back*wanted,params)
    if hit and hit.Position and self:IsCameraBlocker(hit) then
        wanted=math.max(4,(hit.Position-focus).Magnitude-0.8)
    end
    local current=self.CameraCurrentDistance or wanted
    local rate=wanted<current and 10 or 2.5
    current=current+(wanted-current)*(1-math.exp(-rate*math.min(dt,0.1)))
    self.CameraCurrentDistance=current
    camera.CFrame=env.CFrame.lookAt(focus+back*current,focus)
end

---------------------------------------------------------------------------
-- Dribble choice. Reactive picks plus coordinated escape moves.
---------------------------------------------------------------------------
function Extension:ChooseDribble(root, point, opponents, ball)
    if not point or not ball or (self.Plan and self.Plan.Kind=="hesitate" and self.Clock < self.Plan.Until)
        or self.Clock<(self.DribbleDecisionUntil or -100) then return end
    local threat,nearest=nil,16
    for _,opponent in ipairs(opponents)do
        local d=flat(opponent.Predicted-root.Position).Magnitude
        if d<nearest then threat,nearest=opponent,d end
    end
    local right=root.CFrame.RightVector
    local handPart=ballPart(ball)
    local hand=handPart and flat(handPart.Position-root.Position):Dot(right) or 0
    local threatSide=threat and flat(threat.Predicted-root.Position):Dot(right) or 0
    local routeSide=flat(point-root.Position):Dot(right)
    -- Protect the opposite hand from the defender. Do not cross toward a
    -- steal threat just to keep producing keys; open lanes need no move.
    local safeSide=threatSide>0.6 and -1 or (threatSide< -0.6 and 1 or (routeSide>=0 and 1 or -1))
    local exposed=hand*threatSide>0.15
    local candidates={}
    local function add(name) if name~=self.LastMove then candidates[#candidates+1]=name end end
    if exposed and math.abs(hand)>0.2 then
        add(safeSide>0 and "F" or "G") -- safe transfer gets first chance
    else
        -- Random fast chains preserve the protected hand rather than using
        -- a blind crossover or hand switch into the defender.
        add("R");add("V");add("B")
        if not threat then add("C");add("H");add("F");add("G") end
        for i=#candidates,2,-1 do local j=math.random(i);candidates[i],candidates[j]=candidates[j],candidates[i] end
    end
    for _,move in ipairs(candidates)do
        if self:PulseDribble(move) then
            self.DribbleDecisionUntil=self.Clock+0.1
            self.DribbleStatus="Chain "..move.." | protect "..(safeSide>0 and "right" or "left")
            return
        end
    end
    self.DribbleStatus="Chain waiting: safe moves busy or action in progress"

end
-- Move that carries the ball to the escape side: behind-the-back from the
-- off hand, a cross when already on that side, or a fake toward the other
-- side when the defender is square.
function Extension:EscapeMove(side, hand, square)
    if hand*side>0.2 then return nil end -- already protected: do not cross back into contact
    if square then return side > 0 and "V" or "B" end
    if math.abs(hand)>0.2 then return side>0 and "F" or "G" end
    return nil -- unknown ball hand: move to safety without guessing a crossover

end
-- Commit to a short lateral escape or hesitation when an on-ball defender
-- is in the path. Committed plans prevent left/right flip-flopping; a cap per
-- possession prevents endless circling.
function Extension:PlanEscape(root, destination, opponents, ball)
    local now = self.Clock
    local plan = self.Plan
    if plan then
        local reached = plan.Point and flat(plan.Point-root.Position).Magnitude < 1
        if now < plan.Until and not reached then return plan end
        self.Plan = nil
        if plan.Kind == "escape" then
            -- Completion check: did the escape create separation?
            local still = false
            for _, opponent in ipairs(opponents) do
                if flat(opponent.Position-root.Position).Magnitude < 4 then still = true end
            end
            self.EscapeFailed = self.EscapeFailed or {}
            self.EscapeFailed[plan.Side] = still and now or nil
        end
        if plan.Kind == "hesitate" then self.NextEscape = now else self.NextEscape = now+0.7 end
        plan = nil
    end
    if (self.EscapeCount or 0) >= 4 or now < (self.NextEscape or -100) then return nil end
    local forward = unit(flat(destination-root.Position))
    local lateral = lateralOf(forward)
    local defender, gap = nil, 10
    for _, opponent in ipairs(opponents) do
        local offset = flat(opponent.Position-root.Position)
        local d = offset.Magnitude
        if d < gap and d > 0.01 and unit(offset):Dot(forward) > 0.35 then defender, gap = opponent, d end
    end
    if not defender then return nil end
    local params = self:MakeRayParams()
    local defenderSide = flat(defender.Predicted-root.Position):Dot(lateral)
    local part = ballPart(ball)
    local hand = part and flat(part.Position-root.Position):Dot(root.CFrame.RightVector) or 0
    local square = math.abs(defenderSide) < 1.2
    local preferred
    if square then
        preferred = -(self.LastEscapeSide or 1)
    else preferred = defenderSide > 0 and -1 or 1 end
    local closingSpeed = -flat(defender.Position-root.Position):Dot(defender.Velocity)/math.max(gap,0.01)
    -- Do not repeat a side that just failed to create space.
    local failed = self.EscapeFailed or {}
    if failed[preferred] and now-failed[preferred] < 2 then preferred = -preferred end
    local chosen,bestScore=nil,-math.huge
    for _,side in ipairs({preferred,-preferred})do
        -- At contact, create lateral/backward separation rather than driving
        -- through the handler's hands. Score both exits against every defender.
        local point=root.Position+lateral*side*7+forward*(gap<6 and -2 or 2)
        if self:WalkClear(root.Position,point,params) then
            local clearance=30
            for _,opponent in ipairs(opponents)do
                clearance=math.min(clearance,flat(opponent.Predicted-point).Magnitude)
            end
            local bodySide=(point-root.Position):Dot(root.CFrame.RightVector)>=0 and 1 or -1
            local protected=hand*bodySide>0 and 0.7 or 0
            local score=clearance+protected+(side==preferred and 0.4 or 0)
            if score>bestScore then chosen,bestScore={Side=side,BodySide=bodySide,Point=point},score end
        end
    end
    if not chosen then return nil end
    self.EscapeCount = (self.EscapeCount or 0)+1
    self.LastEscapeSide = chosen.Side
    if closingSpeed > 8 and gap >= 6 and gap < 10 and self.Clock-((self.MoveCooldowns or {}).R or -100) >= 0.4 then
        -- Hesitation: plant briefly with a fake-out, then escape away from
        -- where the defender committed.
        self.Plan = {Kind="hesitate", Until=now+0.22, Side=chosen.Side, Facing=forward}
        self:PulseDribble("R")
        self.EscapeCount = self.EscapeCount-1
        return self.Plan
    end
    self.Plan = {Kind="escape", Until=now+0.5, Side=chosen.Side, Point=chosen.Point, Facing=forward}
    local move=self:EscapeMove(chosen.BodySide,hand,square and gap>7)
    if move then self:PulseDribble(move) end
    return self.Plan
end

---------------------------------------------------------------------------
-- Dunks
---------------------------------------------------------------------------
function Extension:TryDunk(root, goal)
    local reach=flat(goal.Position-root.Position).Magnitude
    if reach>(self.DunkReach or 9) then return false end
    if not self:PulseKey("T",0.65,1.2,true) then return false end
    self.DunkAttempts=(self.DunkAttempts or 0)+1
    self.LastShotResult="Dunk key T sent at "..string.format("%.1f",reach).." studs"
    self.AutoPlayStatus="Dunking"
    self.DunkingUntil=nil -- Input is not proof the server started a dunk.
    if self.StartShotTrack then self:StartShotTrack("Dunk", self.Player.Character, goal, reach) end
    return true
end

---------------------------------------------------------------------------
-- Offense decision loop (10 Hz)
---------------------------------------------------------------------------
function Extension:OffenseStep(character, humanoid, root)
    if self.Shooting then self:StopAutoMove();return false end
    if self.OffenseCharacter ~= character then self:ResetOffense();self.OffenseCharacter=character end
    local now = self.Clock
    self.PreparingShot=false
    self.PossessionStart = self.PossessionStart or now
    local held = now-self.PossessionStart
    local action = gameAction(character)
    if action == "Shooting" or action == "Dunking" then
        self.FreezeSince = self.FreezeSince or now
        if now-self.FreezeSince > 2.5 then
            if not self.FreezeLogged and self.Log then self:Log("watchdog", "Action "..tostring(action).." stale >2.5s: resuming") end
            self.FreezeLogged = true; action = nil
        end
    else self.FreezeSince, self.FreezeLogged = nil, nil end
    if action == "Shooting" or action == "Dunking" then
        self:StopAutoMove();self:ReleaseDribbleKeys(true)
        self.AutoPlayStatus = "Game action in progress: "..tostring(action or "dunk")
        return false
    end
    if not self.OffenseGoal or not self.OffenseGoal.Parent then
        self.OffenseGoal = self.MatchGoal or self:NearestGoal(root,self.Settings.AutoPlayBasket)
        if not self.OffenseGoal then self:StopAutoMove();self.AutoPlayStatus="No nearby attack basket";return false end
        self.GoalDirection = unit(flat(root.Position-self.OffenseGoal.Position))
    end
    local goal=self.OffenseGoal
    local opponents = self:ReadOpponents(root)
    self.OpponentReads = opponents
    local space, jumping = self:SpaceAt(root.Position,opponents)
    local grounded = humanoid.FloorMaterial ~= self.Environment.Enum.Material.Air
    local rimDistance = distance(root.Position,goal.Position)
    local minimum = self.Settings.AimbotType == "High" and 57 or 58
    local params = self:MakeRayParams()
    self.ForceShot = held >= 8
    -- Rim attack: inside the jumper ring the calibrated shot cannot score, so
    -- drive and dunk instead of backing out. Also drive from the near edge of
    -- the ring when pressed hard and the corridor to the rim is empty.
    if self.Settings.AutoPlayDunk ~= false then
        if rimDistance < minimum-3 then self.DunkMode=true
        elseif rimDistance > minimum and not (self.DriveUntil and now < self.DriveUntil) then self.DunkMode=false end
        if not self.DunkMode and space < 5 and rimDistance < 64 and held < 5 then
            local corridor = true
            for _, opponent in ipairs(opponents) do
                if segmentDistance(opponent.Predicted, root.Position, goal.Position) < 4
                    and flat(opponent.Position-goal.Position).Magnitude < rimDistance then corridor = false end
            end
            if corridor then self.DunkMode, self.DriveUntil = true, now+3 end
        end
    else self.DunkMode=false end
    if self.DunkMode then
        self.OpenSince,self.SettlePosition,self.SettleSince=nil,nil,nil
        if grounded then self:TryDunk(root,goal) end
        local approach = unit(flat(root.Position-goal.Position))
        local rim=goal.Position+approach*2.5
        rim=self.Environment.Vector3.new(rim.X,root.Position.Y,rim.Z)
        local plan = self:PlanEscape(root, rim, opponents, heldBall(character))
        local point = plan and plan.Point
        if not point and not plan then
            point=self:SteerTo(root,rim,opponents) or (flat(rim-root.Position).Magnitude>0.6 and rim or nil)
        end
        if plan and plan.Kind=="hesitate" then self:StopAutoMove();self.AutoPlayStatus="Hesitation at the rim"
        elseif point then
            self.AutoMovePoint=point;self.AutoPlayStatus=plan and "Rim drive: lateral escape" or "Driving to the rim"
            if not plan then self:ChooseDribble(root,point,opponents,heldBall(character)) end
        else self:StopAutoMove();self.AutoPlayStatus="At the rim" end
        return false
    end
    local canShoot = self:CanTakeShot(root)
    if canShoot and grounded then
        local contested = space < 10 or jumping
        -- Sweet spot: open and early in the possession, take one more step
        -- into the middle of the calibrated power table.
        local high = self.Settings.AimbotType == "High"
        local low, top = high and 59 or 60, high and 71 or 72
        if not contested and held < 0.5 and (rimDistance < low or rimDistance > top) and self.ShotSpot then
            local point = self:SteerTo(root,self.ShotSpot,opponents)
            if point then self.AutoMovePoint=point;self.AutoPlayStatus="Stepping into the sweet spot";return false end
        end
        self.PreparingShot=true
        self:StopAutoMove();self:ReleaseDribbleKeys(true)
        self.Plan = nil
        -- Pump fake: a defender already in the air close by will come down
        -- before we release. Bounded to 0.45 s so it never stalls.
        local blocker = false
        for _, opponent in ipairs(opponents) do
            if opponent.Airborne and flat(opponent.Position-root.Position).Magnitude < 7 then blocker = true end
        end
        if blocker then
            self.FakeShotStart = self.FakeShotStart or now
            if now-self.FakeShotStart < 0.25 then
                if now-self.FakeShotStart < 0.05 then self:PulseKey("R",0.04,0.4,true) end
                self.AutoPlayStatus="Pump fake: defender in the air";return false
            end
        end
        if contested then self.AutoPlayStatus="Contested shot";self.FakeShotStart=nil;return true end
        if not self.SettlePosition or flat(root.Position-self.SettlePosition).Magnitude > 0.7 then
            self.SettlePosition,self.SettleSince=root.Position,now
        end
        local stationary = flat(root.AssemblyLinearVelocity).Magnitude < 3
            or now-(self.SettleSince or now)>=0.06
        if not stationary then self.AutoPlayStatus="Stopping for shot";return false end
        self.OpenSince = self.OpenSince or now
        self.AutoPlayStatus="Open shot: settling"
        if now-self.OpenSince >= 0.06 then self.FakeShotStart=nil;return true end
        return false
    end
    self.OpenSince=nil
    self.SettlePosition,self.SettleSince=nil,nil
    if canShoot then self:StopAutoMove();self.AutoPlayStatus="Stopping for shot";return false end
    -- Shot clock: after 4.5 s stop shopping for the perfect spot and attack
    -- the nearest legal point on the ring in a straight line.
    self.AttackMode = held >= 4.5
    if self.AttackMode then
        local radius = self:ShotRadius(root, goal)
        local spot = goal.Position+unit(flat(root.Position-goal.Position))*radius
        self.ShotSpot = self.Environment.Vector3.new(spot.X,root.Position.Y,spot.Z)
    elseif not self.LastPlan or now-self.LastPlan >= 0.35 or not self.ShotSpot then
        self.LastPlan=now;self:PickShotSpot(root,opponents,params)
    end
    if not self.ShotSpot then self:StopAutoMove();self.AutoPlayStatus="No supported shot position";return false end
    if not self.ProgressTime then self.ProgressTime,self.ProgressPosition=now,root.Position
    elseif now-self.ProgressTime >= 1.5 then
        if flat(root.Position-self.ProgressPosition).Magnitude < 0.6 then
            self.EscapeSide=-(self.EscapeSide or 1);self.StuckUntil=now+1.2;self.LastPlan=nil
        end
        self.ProgressTime,self.ProgressPosition=now,root.Position
    end
    local plan = not self.AttackMode and self:PlanEscape(root, self.ShotSpot, opponents, heldBall(character)) or nil
    if plan and plan.Kind == "hesitate" then
        self:StopAutoMove();self.AutoPlayStatus="Hesitation: reading the defender";return false
    end
    local point = plan and plan.Point or self:SteerTo(root,self.ShotSpot,self.AttackMode and {} or opponents)
    if point then
        self.AutoMovePoint=point
        if plan then self.AutoPlayStatus=(plan.Side>0 and "Escape right" or "Escape left")
        elseif self.AttackMode then self.AutoPlayStatus="Shot clock: attacking the ring"
        else self.AutoPlayStatus=jumping and "Reading defender jump: creating space" or (space < 12 and "Evading defender" or "Routing to shot position") end
        if not plan then self:ChooseDribble(root,point,opponents,heldBall(character)) end
    else self:StopAutoMove();self:ReleaseDribbleKeys(true);self.AutoPlayStatus="Route blocked: waiting to replan" end
    return false
end

---------------------------------------------------------------------------
-- Shot / dunk verification from available game state: input dispatched,
-- Hoopz Action attribute, ball leaving the hand, closest ball-to-rim pass.
---------------------------------------------------------------------------
function Extension:StartShotTrack(kind, character, goal, reach)
    self.AttemptSerial=(self.AttemptSerial or 0)+1
    local power="?";pcall(function()power=tostring(self.Player:GetAttribute("Power"))end)
    self:Log("attempt",string.format("#%d %s routine completed | arc=%s power=%s delay=%s goal=%s",
        self.AttemptSerial,kind,tostring(self.Settings.AimbotType),power,tostring(self.Settings.ShotDelay),self:GoalLabel(goal)))
    self.ShotTrack = {Kind=kind, Character=character, Goal=goal, Start=self.Clock, Reach=reach,
        Released=false, MinDistance=math.huge, Ball=self.PossessionBall}
end
function Extension:FinishShotTrack(text)
    local track = self.ShotTrack
    self.ShotTrack = nil
    if not track then return end
    if track.Action then text = text.." [Action="..tostring(track.Action).."]" end
    self.LastShotResult = text
    if self.Log then self:Log(track.Kind == "Dunk" and "dunk" or "shot", text) end
    if track.Kind == "Dunk" then
        if track.Released or track.Action == "Dunking" then
            self.DunksStarted = (self.DunksStarted or 0)+1
        else
            -- T was not accepted from this distance: try closer next time.
            self.DunkReach = math.max(4, (self.DunkReach or 9)-2)
            self.LastShotResult = text.."; next dunk at "..tostring(self.DunkReach).." studs"
        end
    end
end
function Extension:TrackShot()
    local track = self.ShotTrack
    if not track then return end
    local character = track.Character
    if self.Player.Character ~= character then self:FinishShotTrack("Cancelled: character changed"); return end
    local action = gameAction(character)
    if action == "Shooting" or action == "Dunking" then track.Action = action end
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if not track.Released then
        if heldBall(character) then
            track.LeftAt = nil
            if self.Clock-track.Start > 1.0 then
                self:FinishShotTrack(track.Kind == "Dunk" and "Dunk: no dunk state and ball still held"
                    or "Shot input sent but ball still held after 1s")
            end
            return
        end
        -- Out of our hands: confirm it is a release, not a dribble reparent
        -- (regained within 0.3 s) or a strip (an opponent now holds it).
        track.LeftAt = track.LeftAt or self.Clock
        local kind, who = self.ReadPossession and self:ReadPossession(character)
        if kind == "Opponent" then
            self:FinishShotTrack("Not a release: ball taken by "..tostring(who and who.Name or "opponent"))
            return
        end
        if self.Clock-track.LeftAt < 0.15 then return end
        track.Released, track.ReleaseTime = true, self.Clock
        -- Bind to one ball: the loose ball nearest to us at release.
        local best, bestDistance = track.Ball, nil
        for part in pairs(self:BallSet()) do
            if not track.Ball and part.Parent and not self:BallOwner(part) and root
                and (not self.MatchGoal or self:MatchPosition(part.Position)) then
                local d = (part.Position-root.Position).Magnitude
                if d<40 and (not bestDistance or d < bestDistance) then best, bestDistance = part, d end
            end
        end
        track.Ball = best
        if track.Kind == "Shot" then self.ShotsReleased = (self.ShotsReleased or 0)+1 end
        return
    end
    local goal = track.Goal
    local ball = track.Ball
    if goal and goal.Parent and ball and ball.Parent then
        local d = (ball.Position-goal.Position).Magnitude
        if d < track.MinDistance then track.MinDistance = d end
    end
    local elapsed = self.Clock-track.ReleaseTime
    local regained = heldBall(character) ~= nil
    if elapsed >= 2.5 or (regained and elapsed > 0.3) then
        local closest = track.MinDistance
        local text
        if track.Kind == "Dunk" then text = "Dunk released"
        elseif closest == math.huge then text = "Shot released (ball flight not tracked)"
        elseif closest <= 3.5 then
            self.ShotsNearRim = (self.ShotsNearRim or 0)+1
            text = string.format("Shot released; passed %.1f studs from rim (score not verifiable)", closest)
        else text = string.format("Shot released; closest %.1f studs from rim", closest) end
        self:FinishShotTrack(text)
    end
end

-- Keep all decisions on one local court. Never acquire a server-wide holder
-- first and then let that stranger choose the defended basket.
local function attribute(object,key)
    if object and type(object.GetAttribute)=="function" then
        local ok,value=pcall(object.GetAttribute,object,key)
        if ok and (type(value)=="string" or type(value)=="number" or type(value)=="boolean") then return value end
    end
end
local function mflat(v)return Extension.Environment.Vector3.new(v.X,0,v.Z)end
function Extension:GoalLabel(goal)
    if not goal then return "unlocked" end
    local path=goal.Name or "Goal"
    if type(goal.GetFullName)=="function" then local ok,v=pcall(goal.GetFullName,goal);if ok then path=v end end
    local p=goal.Position
    return path..string.format(" [%.0f,%.0f,%.0f]",p.X,p.Y,p.Z)
end
function Extension:LockMatch(goal)
    local _,_,root=characterParts(self.Player)
    if not root then return end
    goal=goal or self:NearestGoal(root,self.Settings.AutoPlayBasket)
    self.MatchGoal,self.MatchChoice=goal,self.Settings.AutoPlayBasket
    self.MatchOpponent=nil
    self.MatchAnchor=root.Position
    self.ContextReason=goal and "court locked at local player" or "no local basket"
    self.DefenseGoal,self.LastDefenseTarget,self.Holder=nil,nil,nil
    self.RecoveryBall,self.RecoveryUntil=nil,nil
    if self.ResetOffense then self:ResetOffense() end
    self:StopAutoMove()
    self.State,self.PendingState=nil,nil
    self:Log("match",self.ContextReason..": "..self:GoalLabel(goal))
end
function Extension:EnsureMatch()
    if self.MatchChoice~=self.Settings.AutoPlayBasket or (not self.MatchGoal or not self.MatchGoal.Parent)
        and self.Clock>=(self.NextContextLock or -100) then
        self.NextContextLock=self.Clock+1;self:LockMatch()
    end
    return self.MatchGoal
end
function Extension:MatchPosition(position)
    local goal=self.MatchGoal
    if not goal then return true end -- legacy isolated unit fixtures only
    if math.abs(position.Y-goal.Position.Y)>45 or mflat(position-goal.Position).Magnitude>125 then return false end
    -- Voronoi boundary prevents crossing into an adjacent half court. A small
    -- margin admits bodies/balls on the shared painted boundary.
    local d=mflat(position-goal.Position).Magnitude
    for _,other in ipairs(self:Goals())do
        if other~=goal and other.Parent and math.abs(other.Position.Y-goal.Position.Y)<15
            and mflat(position-other.Position).Magnitude+8<d then return false end
    end
    return true
end
function Extension:MatchPlayer(player)
    local _,_,root=characterParts(player)
    if not root or not self:MatchPosition(root.Position) then return false end
    if attribute(self.Player,"Ingame")==true and attribute(player,"Ingame")==false then return false end
    for _,key in ipairs({"Court","CourtId","CourtID","MatchId","MatchID","GameId"})do
        local ours=attribute(self.Player,key) or attribute(self.Player.Character,key)
        local theirs=attribute(player,key) or attribute(player.Character,key)
        if ours~=nil and theirs~=nil and ours~=theirs then return false end
    end
    local selected=self.Settings.AutoPlayOpponent
    if selected and selected~="Auto (this court)" and player~=self.Player then return player.Name==selected end
    return true
end
function Extension:SelectMatchHolder(character)
    self:EnsureMatch()
    local own=heldBall(character)
    if own then
        local ok,part=pcall(function() return own:IsA("BasePart") and own or own:FindFirstChild("Ball") end)
        if ok then self.PossessionBall=part end
        return "Own",self.Player
    end
    local _,_,root=characterParts(self.Player)
    if not root then return "Loose",nil end
    if not self.MatchGoal or not self.MatchGoal.Parent then self.ContextReason="No court locked: use Lock viewed hoop";return "Loose",nil end
    local candidates={}
    for _,player in ipairs(self:PlayerList())do
        if player~=self.Player and self:MatchPlayer(player) and heldBall(player.Character) then
            local teammate=self.Player.Team~=nil and player.Team==self.Player.Team
                and self.Player.Neutral==false and player.Neutral==false
            local _,_,other=characterParts(player)
            candidates[#candidates+1]={Player=player,Kind=teammate and "Teammate" or "Opponent",Distance=(root.Position-other.Position).Magnitude}
        end
    end
    for _,c in ipairs(candidates)do if c.Player==self.MatchOpponent then return c.Kind,c.Player end end
    -- Once the opponent is known, do not replace them with another server
    -- player holding a different ball during a release or dribble.
    if self.MatchOpponent and self:MatchPlayer(self.MatchOpponent) then return "Loose",nil end
    table.sort(candidates,function(a,b)return a.Distance<b.Distance end)
    local first=candidates[1]
    if first and candidates[2] and candidates[2].Distance-first.Distance<10 then
        self.ContextReason="multiple holders on court: select Opponent";return "Loose",nil
    end
    if first then
        if first.Kind=="Opponent" then
            self.MatchOpponent=first.Player
            self:Log("match","opponent locked "..first.Player.Name.." | "..self:GoalLabel(self.MatchGoal))
        end
        return first.Kind,first.Player
    end
    return "Loose",nil
end
function Extension:LockViewedHoop()
    local camera=self.Environment.workspace.CurrentCamera
    if not camera then return end
    local best,score=nil,-1
    for _,goal in ipairs(self:Goals())do
        local delta=goal.Position-camera.CFrame.Position
        if delta.Magnitude<170 and delta.Magnitude>1 then
            local alignment=delta.Unit:Dot(camera.CFrame.LookVector)
            if alignment>0.85 and alignment>score then best,score=goal,alignment end
        end
    end
    if best then self:LockMatch(best) else self.ContextReason="Look toward the intended rim, then lock again";self:Log("match",self.ContextReason) end
end
function Extension:RecoveryStep(character,humanoid,root)
    local preferred=self.RecoveryBall or (self.ShotTrack and self.ShotTrack.Ball)
    local ball,best=nil,85
    for candidate in pairs(self:BallSet())do
        if candidate.Parent and not self:BallOwner(candidate) and self:MatchPosition(candidate.Position) then
            local d=(candidate.Position-root.Position).Magnitude
            if candidate==preferred and d<85 then ball=candidate;break end
            if d<best then ball,best=candidate,d end
        end
    end
    if not ball then self:StopAutoMove();self.StopReason="no loose ball on locked court";self.AutoPlayStatus="Watching court for rebound";return end
    local velocity=ball.AssemblyLinearVelocity or self.Environment.Vector3.new()
    local gravity=self.Environment.workspace.Gravity or 196.2
    local height=math.max(0,ball.Position.Y-root.Position.Y)
    local t=math.min(1.2,math.max(0,(velocity.Y+math.sqrt(velocity.Y*velocity.Y+2*gravity*height))/gravity))
    local lead=mflat(velocity)*math.min(t,0.9)
    if lead.Magnitude>25 then lead=lead.Unit*25 end
    local point=self.Environment.Vector3.new(ball.Position.X,root.Position.Y,ball.Position.Z)+lead
    if not self:MatchPosition(point) then point=self.Environment.Vector3.new(ball.Position.X,root.Position.Y,ball.Position.Z) end
    local params=self:MakeRayParams()
    if not self:HasFloor(point,params) then self:StopAutoMove();self.StopReason="rebound landing point unsupported";return end
    local target=self:SteerTo(root,point,self:ReadOpponents(root))
    self.AutoMovePoint=target
    self.RecoveryTarget,self.RecoveryBall=point,ball
    self.AutoPlayStatus=height>5 and "Rebounding: predicting landing" or "Recovering loose ball"
    self.StopReason=target and nil or "at recovery point"
end

-- Basket-aware defense for Auto-play. Hoopz half-court play attacks one hoop;
-- the defended basket is the goal on the attacker's court (nearest to the
-- attacker, kept for the possession), never simply the hoop nearest to us.
local function dflat(v) return Extension.Environment.Vector3.new(v.X, 0, v.Z) end
local function dunit(v)
    local m = v.Magnitude
    if m < 0.001 then return Extension.Environment.Vector3.new(1, 0, 0) end
    return v / m
end
local function dsegment(point, a, b)
    local d = dflat(b-a)
    local t = math.max(0, math.min(1, dflat(point-a):Dot(d) / math.max(0.001, d:Dot(d))))
    return dflat(point-(a+d*t)).Magnitude
end
function Extension:DefendedGoal(attackerRoot)
    if self.MatchGoal and self.MatchGoal.Parent then
        self.DefenseGoal=self.MatchGoal
        return self.MatchGoal
    end
    local current = self.DefenseGoal
    local best, bestDistance
    for _, goal in ipairs(self:Goals()) do
        if goal.Parent and math.abs(goal.Position.Y-attackerRoot.Position.Y) < 30 then
            local d = dflat(goal.Position-attackerRoot.Position).Magnitude
            if d <= 150 and (not bestDistance or d < bestDistance) then best, bestDistance = goal, d end
        end
    end
    if current and current.Parent and best ~= current then
        local d = dflat(current.Position-attackerRoot.Position).Magnitude
        -- Sticky: only switch when the other hoop is clearly the attacker's.
        if d <= 150 and d < bestDistance+25 then return current end
    end
    if best ~= current then
        self.DefenseGoal = best
        if best and self.Log then self:Log("defense", "defending basket "..tostring(best.Name)) end
    end
    return best
end
function Extension:AttackerRead(attacker, root)
    for _, read in ipairs(self.OpponentReads or {}) do
        if read.Player == attacker then return read end
    end
    return nil
end
-- One defensive decision. Returns the movement target (or nil to hold) and
-- the reason, plus sets DefenseFacing toward the attacker.
function Extension:DefenseStep(character, humanoid, root, attacker)
    local _, attackerHumanoid, attackerRoot = characterParts(attacker)
    if not attackerRoot then self:StopAutoMove(); self.DefenseIntent = "No live attacker"; return nil end
    self.OpponentReads = self:ReadOpponents(root)
    local goal = self:DefendedGoal(attackerRoot)
    if not goal then self:StopAutoMove(); self.DefenseIntent = "No basket on the attacker's court"; return nil end
    local read = self:AttackerRead(attacker, root)
    local velocity = read and read.Velocity or dflat(attackerRoot.AssemblyLinearVelocity)
    if velocity.Magnitude > 32 then velocity = dunit(velocity)*32 end
    local here = root.Position
    local gap = dflat(attackerRoot.Position-here).Magnitude
    local lead = math.max(0.2, math.min(0.5, 0.2+gap/50))
    local rim = self.Environment.Vector3.new(goal.Position.X, here.Y, goal.Position.Z)
    -- Lead drives toward the rim fully; side-to-side crossovers only a
    -- little, enough to offset our slower lateral speed without overshooting.
    local axis = dunit(dflat(rim-attackerRoot.Position))
    local driveVelocity = axis*math.max(0, velocity:Dot(axis))
    local sideVelocity = velocity-axis*velocity:Dot(axis)
    local predicted = attackerRoot.Position+driveVelocity*lead+sideVelocity*0.3
    local attackerFlat = self.Environment.Vector3.new(predicted.X, here.Y, predicted.Z)
    local toRim = dflat(rim-attackerFlat)
    local rimDistance = toRim.Magnitude
    local direction = dunit(toRim)
    local lateral = self.Environment.Vector3.new(-direction.Z, 0, direction.X)
    local driveSpeed = velocity:Dot(direction)
    local shooterRange = (goal.Position-attackerRoot.Position).Magnitude <= 80
    -- How far along the attacker->rim axis we are; <= 0.5 means level/behind.
    local along = dflat(here-attackerFlat):Dot(direction)
    local mode, spacing
    if along < 0.5 and gap < 20 then
        mode = "Recover"
        spacing = math.min(rimDistance*0.6, 9)
        -- Beaten on a drive close to the basket: sprint to the rim itself
        -- instead of chasing the attacker's back.
        if rimDistance < 30 and driveSpeed > 4 then spacing = math.max(spacing, rimDistance-3) end
    elseif rimDistance < 22 or (driveSpeed > 8 and rimDistance < 60) then
        mode = "Protect rim"
        spacing = math.max(2.5, math.min(6, rimDistance*0.35))
    elseif shooterRange then
        mode = "Close out"
        spacing = 4
    else
        mode = "Contain"
        spacing = 6
    end
    spacing = math.min(spacing, math.max(0.5, rimDistance-1))
    local target = attackerFlat+direction*spacing
    -- Recover around the attacker, not through him.
    if mode == "Recover" and dsegment(attackerFlat, here, target) < 2.5 then
        local side = dflat(here-attackerFlat):Dot(lateral) >= 0 and 1 or -1
        target = attackerFlat+lateral*side*4+direction*2
    end
    -- Never drift farther from the basket than the attacker (out of bounds /
    -- onto another court), and keep on supported floor.
    if dflat(target-rim).Magnitude > dflat(attackerFlat-rim).Magnitude+2 then
        target = attackerFlat+direction*math.max(spacing, 2)
    end
    local params = self:MakeRayParams()
    if params and not self:HasFloor(target, params) then
        target = self.LastDefenseTarget or here
    end
    self.LastDefenseTarget = target
    self.DefenseFacing = dunit(dflat(attackerRoot.Position-here))
    self.DefenseGoalPosition = rim
    -- Contest only real shots/dunks or a rising jump close in front.
    local attackerAction = self.GameAction and self:GameAction(attacker.Character)
    local rising = attackerHumanoid.FloorMaterial == self.Environment.Enum.Material.Air
        and attackerRoot.AssemblyLinearVelocity.Y > 8
    if (attackerAction == "Shooting" or attackerAction == "Dunking" or rising) and gap < 9 and along > -1
        and humanoid.FloorMaterial ~= self.Environment.Enum.Material.Air and self.Clock-self.LastJump >= 0.6 then
        humanoid.Jump, self.LastJump = true, self.Clock
        self.ContestCount = (self.ContestCount or 0)+1
        if self.Log then self:Log("defense", "contest jump ("..tostring(attackerAction or "rising")..")") end
    end
    self.DefenseMode = mode
    if dflat(target-here).Magnitude < 1 then
        self:StopAutoMove()
        self.DefenseIntent = mode..": holding good basket-side spot"
        return nil
    end
    self.AutoMovePoint = target
    self.DefenseIntent = mode
    return target
end

